// Generated by TyraX. Do not edit - regenerated on every build.
#include "game_runtime.gen.hpp"

namespace Endless_scroller {
  // never pull closer than this to the head
// --- the collision box -------------------------------------------------------
// One builder for the box every collision consumer reduces an object to (the
// walker's box mode, the camera's spring arm, the split-screen band cull and,
// in a debug build, the wireframe overlay). Host twin: placement::collisionBox.
bool TerrainGame::objectCollides(const SceneObjectData& d) {
  if (d.collision == 2) return false;  // "none" opts out
  switch (d.type) {
    // Everything with no geometry in the game. This list used to be written
    // out by number at each call site, and they had drifted: the scroller belt
    // marker (19) was missing from the camera sweep, so an invisible belt
    // origin pushed the boom in.
    case 4:   // spawn point
    case 6:   // player marker
    case 7:   // particle emitter
    case 8:   // sound emitter
    case 9:   // point light
    case 11:  // empty
    case 13:  // decal
    case 22:  // road - the surface is procChunks; the OBJECT is authoring only
    case 14:  // camera marker
    case 17:  // area (a volume, not a wall)
    case 18:  // procedural volume (authoring only)
    case 19:  // scroller belt marker
    case 20:  // comment (an editor note)
      return false;
    default: return true;
  }
}



TerrainGame::CollisionBox TerrainGame::objectCollisionBox(
    const RuntimeObject& o) const {
  // A model collides as its MESH bounds (a static .tmdl's, or an animated
  // model's baked all-clips AABB) - the unit scale box is only the fallback,
  // and for a model authored standing on its own origin it is its ankles.
  const float* mn = nullptr;
  const float* mx = nullptr;
  if (o.data.type == 5) {
    if (o.data.model >= 0 && o.data.model < (int)gameModels.size()) {
      mn = gameModels[o.data.model].mn;
      mx = gameModels[o.data.model].mx;
#ifdef MODEL_COLL_BOX_USED
      // The model's own, smaller box (docs/collision-boxes.md, "A smaller
      // box") - box mode only: a mesh-mode object collides as its triangles.
      if (o.data.collision != 1 && o.data.model < MODEL_COUNT &&
          MODEL_COLL_BOX[o.data.model][0] > 0.5F) {
        mn = &MODEL_COLL_BOX[o.data.model][1];
        mx = &MODEL_COLL_BOX[o.data.model][4];
      }
#endif
    } else if (o.data.animModel >= 0 &&
               o.data.animModel < (int)gameAnimModels.size()) {
      const SkelModel* anim = gameAnimModels[o.data.animModel].src.get();
      if (anim) mn = anim->min, mx = anim->max;
    }
  }
  const float lmn[3] = {mn ? mn[0] : -0.5F, mn ? mn[1] : -0.5F,
                        mn ? mn[2] : -0.5F};
  const float lmx[3] = {mx ? mx[0] : 0.5F, mx ? mx[1] : 0.5F,
                        mx ? mx[2] : 0.5F};
  CollisionBox b;
  float c[3], h[3];
  for (int k = 0; k < 3; ++k) {
    float a = lmn[k] * o.data.scale[k], e = lmx[k] * o.data.scale[k];
    if (a > e) {  // negative scale mirrors the box, it does not invert it
      const float t = a;
      a = e;
      e = t;
    }
    c[k] = 0.5F * (a + e);
    h[k] = 0.5F * (e - a);
  }
  for (int k = 0; k < 3; ++k) b.center[k] = c[k], b.half[k] = h[k];
  b.yaw = o.data.modelYaw;
  return b;
}



// Debug "show collision boxes" (DEBUG_SHOW_COLLISION): the box every collider
// reduces to, drawn where it actually is. The walker and the camera boom test
// a volume nothing renders, so "why did I stop here", "why did the camera jump
// in" and "why does that character block a doorway sideways" are questions the
// screen cannot answer - this puts the volume on screen, in the same red the
// editor overlay uses (View > Collision boxes), from the SAME objectCollisionBox.
//
// Rebuilt every frame rather than baked into each object's geometry: a box has
// to follow a tumbling physics body and a flow-node-moved prop, and those never
// dirty-rebuild. That is affordable because of two caps - only colliders within
// COLLISION_BOX_RANGE of the camera, and at most COLLISION_BOX_LIMIT of them
// (the nearest win; the rest are silently absent, which is why the range is
// generous rather than the count) - and because an edge is a CROSS of two thin
// quads (12 vertices) instead of a beam box (36): nothing here backface-culls,
// so a cross reads as a solid edge from every angle at a third of the cost.
void TerrainGame::renderCollisionBoxes() {
  if (!DEBUG_SHOW_COLLISION) return;
  const float kRange = COLLISION_BOX_RANGE;
  collisionBoxVerts.clear();
  collisionBoxCols.clear();
  const Color red(255.0F, 48.0F, 48.0F, 128.0F);

  // Nearest-first without a sort: the list is short and a partial insertion
  // over COLLISION_BOX_LIMIT entries costs less than sorting the scene.
  int picked[COLLISION_BOX_LIMIT];
  float pickedD[COLLISION_BOX_LIMIT];
  int count = 0;
  for (int oi = 0; oi < (int)runtimeObjects.size(); ++oi) {
    const RuntimeObject& o = runtimeObjects[oi];
    if (!o.active || !o.visible || !objectCollides(o.data)) continue;
    const float dx = o.data.position[0] - cameraPosition.x;
    const float dy = o.data.position[1] - cameraPosition.y;
    const float dz = o.data.position[2] - cameraPosition.z;
    const float d2 = dx * dx + dy * dy + dz * dz;
    if (d2 > kRange * kRange) continue;
    int at = count;
    if (count == COLLISION_BOX_LIMIT) {
      // full: replace the farthest, and only if this one is nearer
      int worst = 0;
      for (int k = 1; k < count; ++k)
        if (pickedD[k] > pickedD[worst]) worst = k;
      if (pickedD[worst] <= d2) continue;
      at = worst;
    } else {
      ++count;
    }
    picked[at] = oi;
    pickedD[at] = d2;
  }

  for (int k = 0; k < count; ++k) {
    const RuntimeObject& o = runtimeObjects[picked[k]];
    const CollisionBox b = objectCollisionBox(o);
    // The box frame in world space: unit axes plus the world centre.
    const V3 ax[3] = {boxRotate({1.0F, 0.0F, 0.0F}, o.data),
                      boxRotate({0.0F, 1.0F, 0.0F}, o.data),
                      boxRotate({0.0F, 0.0F, 1.0F}, o.data)};
    const V3 cw = boxRotate({b.center[0], b.center[1], b.center[2]}, o.data);
    const float cx = o.data.position[0] + cw.x;
    const float cy = o.data.position[1] + cw.y;
    const float cz = o.data.position[2] + cw.z;
    const float half[3] = {b.half[0], b.half[1], b.half[2]};
    float big = half[0] > half[1] ? half[0] : half[1];
    if (half[2] > big) big = half[2];
    float t = big * 0.02F;  // edge thickness: readable at any box size
    if (t < 0.02F) t = 0.02F;

    auto vtx = [&](float px, float py, float pz) {
      collisionBoxVerts.push_back(Vec4(px, py, pz, 1.0F));
      collisionBoxCols.push_back(red);
    };
    // One quad as two triangles, from four world points.
    auto quad = [&](const V3& p0, const V3& p1, const V3& p2, const V3& p3) {
      vtx(p0.x, p0.y, p0.z);
      vtx(p1.x, p1.y, p1.z);
      vtx(p2.x, p2.y, p2.z);
      vtx(p0.x, p0.y, p0.z);
      vtx(p2.x, p2.y, p2.z);
      vtx(p3.x, p3.y, p3.z);
    };
    for (int a = 0; a < 3; ++a) {
      const int u = (a + 1) % 3, v = (a + 2) % 3;
      for (int corner = 0; corner < 4; ++corner) {
        const float su = (corner & 1) ? 1.0F : -1.0F;
        const float sv = (corner & 2) ? 1.0F : -1.0F;
        // Edge midpoint, then half the edge vector along `a`.
        const float mx = cx + ax[u].x * su * half[u] + ax[v].x * sv * half[v];
        const float my = cy + ax[u].y * su * half[u] + ax[v].y * sv * half[v];
        const float mz = cz + ax[u].z * su * half[u] + ax[v].z * sv * half[v];
        const V3 e = {ax[a].x * half[a], ax[a].y * half[a], ax[a].z * half[a]};
        // Two thin quads crossing along the edge - one spread along u, one
        // along v - so the edge is visible whichever way the camera looks.
        for (int p = 0; p < 2; ++p) {
          const V3& w = p == 0 ? ax[u] : ax[v];
          const V3 wt = {w.x * t, w.y * t, w.z * t};
          quad({mx - e.x - wt.x, my - e.y - wt.y, mz - e.z - wt.z},
               {mx + e.x - wt.x, my + e.y - wt.y, mz + e.z - wt.z},
               {mx + e.x + wt.x, my + e.y + wt.y, mz + e.z + wt.z},
               {mx - e.x + wt.x, my - e.y + wt.y, mz - e.z + wt.z});
        }
      }
    }
  }

  if (collisionBoxVerts.empty()) return;
  if (!batchInfoBag) {
    batchInfoBag = std::make_unique<StaPipInfoBag>();
    batchInfoBag->model = &model;
    batchInfoBag->shadingType = TyraShadingGouraud;
    batchInfoBag->frustumCulling = PipelineInfoBagFrustumCulling_Precise;
    batchInfoBag->fullClipChecks = true;
  }
  if (!collisionBoxBag) {
    collisionBoxColorBag = std::make_unique<StaPipColorBag>();
    collisionBoxBag = std::make_unique<StaPipBag>();
    collisionBoxBag->info = batchInfoBag.get();
    collisionBoxBag->color = collisionBoxColorBag.get();
    collisionBoxBag->lighting = nullptr;
    collisionBoxBag->texture = nullptr;
  }
  collisionBoxCols.bind(collisionBoxColorBag);
  collisionBoxVerts.bind(collisionBoxBag);
  collisionBoxBag->count = static_cast<u32>(collisionBoxVerts.size());
  collisionBoxBag->bboxVersion = ++g_bboxStamp;
  stapip.core.render(collisionBoxBag.get());
}



float TerrainGame::springArm(float px, float py, float pz, float dx, float dy,
                             float dz, float maxDist) const {
  // Camera boom: the camera's own radius, ignoring the carried object (it
  // rides right in front of the face and must never shove the camera).
  return sweepSphere(px, py, pz, dx, dy, dz, maxDist, CAM_RADIUS, carryIndex);
}



float TerrainGame::sweepSphere(float px, float py, float pz, float dx,
                               float dy, float dz, float maxDist, float radius,
                               int skipIndex) const {
  const float r = radius;
  float best = maxDist;

  // Broad-phase key: the boom segment's AABB, expanded by the camera radius.
  const float qx = px + dx * maxDist, qy = py + dy * maxDist,
              qz = pz + dz * maxDist;
  const float sminX = (px < qx ? px : qx) - r, smaxX = (px > qx ? px : qx) + r;
  const float sminY = (py < qy ? py : qy) - r, smaxY = (py > qy ? py : qy) + r;
  const float sminZ = (pz < qz ? pz : qz) - r, smaxZ = (pz > qz ? pz : qz) + r;

  for (int oi = 0; oi < (int)runtimeObjects.size(); ++oi) {
    const RuntimeObject& o = runtimeObjects[oi];
    if (oi == skipIndex) continue;  // the swept object itself
    if (!o.active || !o.visible) continue;
    // Markers, lights, decals, areas, volumes, belts and "collision: none"
    // are not blockers - one list, shared with the walker (objectCollides).
    if (!objectCollides(o.data)) continue;
    // Portal pass-through for a swept body (a throw, the carried object,
    // the carry whisker): the geometry the aimed opening is cut into opens
    // up - collidePlayer's doorway rule, same function.
    if (sweepPassOn && portalDoorwayOpens(o, sweepPassPlane, sweepPassPoint))
      continue;

    // The shared collision box, cast in the box's OWN frame - so a rotated
    // block stops the boom at its real faces instead of leaking through the
    // corners of an axis-aligned stand-in.
    const CollisionBox b = objectCollisionBox(o);
    const float ex = b.half[0], ey = b.half[1], ez = b.half[2];
    const V3 cW = boxRotate({b.center[0], b.center[1], b.center[2]}, o.data);
    const float cx = o.data.position[0] + cW.x;
    const float cy = o.data.position[1] + cW.y;
    const float cz = o.data.position[2] + cW.z;

    // Broad phase: the OBB's own world AABB (rotated half-extent vectors summed
    // per axis), inflated by r, vs the boom segment AABB. Conservative - it
    // never rejects an object the local slab test could still hit (the old
    // scale-box AABB was too small for a rotated block and leaked candidates).
    const V3 hxv = boxRotate({ex, 0.0F, 0.0F}, o.data);
    const V3 hyv = boxRotate({0.0F, ey, 0.0F}, o.data);
    const V3 hzv = boxRotate({0.0F, 0.0F, ez}, o.data);
    const float wex = fabsf(hxv.x) + fabsf(hyv.x) + fabsf(hzv.x);
    const float wey = fabsf(hxv.y) + fabsf(hyv.y) + fabsf(hzv.y);
    const float wez = fabsf(hxv.z) + fabsf(hyv.z) + fabsf(hzv.z);
    if (cx + wex + r < sminX || cx - wex - r > smaxX ||
        cy + wey + r < sminY || cy - wey - r > smaxY ||
        cz + wez + r < sminZ || cz - wez - r > smaxZ)
      continue;  // broad phase: nowhere near the boom

    // Narrow phase: slab test in the box's local frame. The frame is
    // orthonormal, so the hit parameter t is still a world-space distance.
    const V3 lo = boxInvRotate({px - cx, py - cy, pz - cz}, o.data);
    const V3 ld = boxInvRotate({dx, dy, dz}, o.data);
    float t0 = 0.0F, t1 = best;
    bool miss = false;
    auto slab = [&](float o1, float d1, float lo1, float hi1) {
      if (miss) return;
      if (d1 > 1e-6F || d1 < -1e-6F) {
        const float inv = 1.0F / d1;
        float ta = (lo1 - o1) * inv, tb = (hi1 - o1) * inv;
        if (ta > tb) {
          const float s = ta;
          ta = tb;
          tb = s;
        }
        if (ta > t0) t0 = ta;
        if (tb < t1) t1 = tb;
      } else if (o1 < lo1 || o1 > hi1) {
        miss = true;  // parallel and outside the slab
      }
    };
    slab(lo.x, ld.x, -ex - r, ex + r);
    slab(lo.y, ld.y, -ey - r, ey + r);
    slab(lo.z, ld.z, -ez - r, ez + r);
    if (miss || t0 > t1) continue;
    // t0 < 0 = the pivot is already inside this (inflated) box - e.g. the
    // player brushing a wall. Ignore it rather than collapse the camera onto
    // the head; a box we are standing in cannot usefully block the boom.
    if (t0 < 0.0F) continue;
    if (t0 < best) best = t0;
  }

  // Terrain: march the surviving distance, then bisect to tighten the hit.
  // `- r` keeps the eye a radius clear of the ground, and `lo` (the last
  // known-free sample) is the conservative answer.
  const float step = best * 0.125F;
  if (step > 1e-4F) {
    float prev = 0.0F;
    for (int i = 1; i <= 8; ++i) {
      const float t = step * i;
      if (py + dy * t - r <= terrainHeightAt(px + dx * t, pz + dz * t)) {
        float lo = prev, hi = t;
        for (int k = 0; k < 4; ++k) {
          const float mid = (lo + hi) * 0.5F;
          if (py + dy * mid - r <= terrainHeightAt(px + dx * mid, pz + dz * mid))
            hi = mid;
          else
            lo = mid;
        }
        best = lo;
        break;
      }
      prev = t;
    }
  }
  return best;
}



// Dispatcher: walk P1 (and P2 while active) from their pads, then compose the
// frame camera. Shared screen frames the pair with one camera; split screen
// keeps each player's own view (the render pass reads players[1].camPos).
bool TerrainGame::updatePlayerEntity() {
  if (PLAYER_INDEX < 0) return false;

  updatePlayerWalker(players[0], 0, engine->pad);
  const bool p2 =
      MULTIPLAYER_MODE != 0 && playerTwoActive && players[1].objIndex >= 0;
  if (p2) {
    if (MULTIPLAYER_MODE == 1) {
      // Shared screen: P2 moves relative to the one camera - its movement
      // basis mirrors P1's orbit (the walker skips its right stick).
      players[1].yaw = players[0].yaw;
      players[1].pitch = players[0].pitch;
    }
    updatePlayerWalker(players[1], 1, pad2);
  }

  if (p2 && MULTIPLAYER_MODE == 1) {
    updateSharedCamera();
  } else {
    cameraPosition = players[0].camPos;
    cameraLookAt = players[0].camLook;
  }
  return true;
}



void TerrainGame::updatePlayerWalker(PlayerCtl& P, int pi, Tyra::Pad& pad) {
  const auto& leftJoy = pad.getLeftJoyPad();
  const auto& rightJoy = pad.getRightJoyPad();
  // stickAxis applies the per-stick deadzone (g_deadzoneL/R - Preferences, or a
  // menu "Deadzone" option block) and response curve (g_stickCurve*/g_stickExp*
  // - Preferences > Input / Set Stick Curve node / a menu "Aim curve" block).
  // Set Player Input off (g_playerLocked) reads as both sticks centred: it is
  // the ONE funnel every analog read goes through, so nothing downstream needs
  // to know the controls were taken away.
  auto axisL = [&](const u8& raw) {
    return g_playerLocked
               ? 0.0F
               : stickAxis(raw, g_deadzoneL, g_stickCurveL, g_stickExpL);
  };
  auto axisR = [&](const u8& raw) {
    return g_playerLocked
               ? 0.0F
               : stickAxis(raw, g_deadzoneR, g_stickCurveR, g_stickExpR);
  };

  // Right stick: look around (stick right = turn right). A shared-screen P2
  // has no camera of its own (the dispatcher mirrors P1's orbit into it), so
  // only players that own a view read the right stick. A fixed-angle
  // third-person style (top-down / isometric / fixed) additionally pins the
  // pitch every frame - and the yaw too unless the style allows stick
  // rotation - so the camera holds its authored angle while the left stick
  // drives the avatar.
  const bool ownCamera = pi == 0 || MULTIPLAYER_MODE == 2;
  const bool fixedCam = PP_MODE(pi) == 2 && PP_CAM_STYLE(pi) != 0;
  if (ownCamera) {
    if (!fixedCam || PP_CAM_YAW_ROTATE(pi))
      P.yaw -= axisR(rightJoy.h) * 0.05F * PP_LOOK_SPEED(pi) * g_frameScale;
#ifdef TYRAX_KBD_MOUSE
    // Mouse look (controls.hpp): the USB mouse drives player 1 (pad 1). The
    // deltas are the counts accumulated since the previous frame, so no
    // g_frameScale: the same swipe turns the same angle at any frame rate.
    if (pi == 0 && !g_playerLocked && (!fixedCam || PP_CAM_YAW_ROTATE(pi)))
      P.yaw -= engine->kbdMouse.getMouse().dx * 0.003F * MOUSE_SENSITIVITY;
#endif
    if (fixedCam) {
      P.pitch = -PP_CAM_PITCH(pi);  // elevation in radians; down = negative
    } else {
      P.pitch -= axisR(rightJoy.v) * 0.035F * PP_LOOK_SPEED(pi) * g_frameScale;
#ifdef TYRAX_KBD_MOUSE
      if (pi == 0 && !g_playerLocked)
        P.pitch -= engine->kbdMouse.getMouse().dy * 0.003F * MOUSE_SENSITIVITY;
#endif
      if (P.pitch > 1.35F) P.pitch = 1.35F;
      if (P.pitch < -1.35F) P.pitch = -1.35F;
    }
  }

  const float fx = sinf(P.yaw);
  const float fz = cosf(P.yaw);
  const float forward = -axisL(leftJoy.v);
  const float strafe = axisL(leftJoy.h);

  // The three speed tiers (docs/player-speeds.md). The stick's DEFLECTION
  // ramps the speed from walk to run, so easing the stick walks and pushing it
  // all the way runs; a digital source (d-pad, keyboard) always reads full
  // deflection and therefore always runs. Holding the "sprint" action pins the
  // top speed FLAT instead of ramping - a deliberate go-fast modifier.
  //
  // Both tiers are RESOLVED at build time (project::playerRunSpeed /
  // playerSprintSpeed), so a project that set neither has RUN == WALK - the
  // ramp is then a no-op - and SPRINT == walk x SPRINT_MULT, which is the
  // expression this used to compute here. That is what makes an existing
  // project move exactly as it did.
  //
  // forward/strafe are each -1..1 and already carry the stick's magnitude into
  // the position delta below, so the ramp must scale the SPEED only; the clamp
  // matters because a d-pad diagonal reads sqrt(2).
  float stickMag = sqrtf(forward * forward + strafe * strafe);
  if (stickMag > 1.0F) stickMag = 1.0F;
  const bool sprinting =
      IA_ROLE_SPRINT >= 0 && inputPressed(pad, IA_ROLE_SPRINT);
  const float moveSpeed =
      sprinting ? P.speeds[2]
                : P.speeds[0] + (P.speeds[1] - P.speeds[0]) * stickMag;

  if (PP_MODE(pi) == 1) {
    // Noclip: fly where the camera looks; X up, Square down.
    const float cp = cosf(P.pitch);
    const float step = moveSpeed * g_frameScale;
    P.x += (fx * cp * forward - fz * strafe) * step;
    P.z += (fz * cp * forward + fx * strafe) * step;
    P.y += sinf(P.pitch) * forward * step;
    if (!g_playerLocked && inputPressed(pad, IA_ROLE_FLY_UP)) P.y += step;
    if (!g_playerLocked && inputPressed(pad, IA_ROLE_FLY_DOWN)) P.y -= step;

    P.camPos = Vec4(P.x, P.y, P.z);
    P.camLook = Vec4(P.x + fx * cp, P.y + sinf(P.pitch), P.z + fz * cp);
    return;
  }

  if (PP_MODE(pi) == 2) {
    // Third person: the left stick moves the avatar relative to the camera,
    // the avatar turns to face where it walks, and the camera rides a boom
    // behind it. Terrain bounds + object collision + gravity/jump match walk.
    float nextX = P.x + (fx * forward - fz * strafe) * moveSpeed * g_frameScale;
    float nextZ = P.z + (fz * forward + fx * strafe) * moveSpeed * g_frameScale;
    const float limX = TERRAIN_WIDTH * 0.5F - 1.0F;
    const float limZ = TERRAIN_DEPTH * 0.5F - 1.0F;
    if (nextX > limX) nextX = limX;
    if (nextX < -limX) nextX = -limX;
    if (nextZ > limZ) nextZ = limZ;
    if (nextZ < -limZ) nextZ = -limZ;

    float ground = walkGroundAt(nextX, nextZ, P.y);
    // a linked floor portal underfoot swallows the avatar too
    if (PORTAL_COUNT > 0 && portalSwallowsPlayer(nextX, P.y, nextZ))
      ground = -1e30F;
    float ceiling = 1e30F;
    // The avatar shoves physics bodies exactly like the FPP walkers do.
    pushPhysicsBodies(P.x, P.z, nextX, nextZ, P.y, PP_EYE_HEIGHT(pi));
    updatePortalPass(nextX, P.y, nextZ);  // wall doorways open in collision
    collidePlayer(P.x, P.z, &nextX, &nextZ, P.y, PP_EYE_HEIGHT(pi), &ground,
                  &ceiling);
    // The whisker reads portalPassOn to keep the mounting wall open while
    // carrying THROUGH a portal - reset it only after the whisker runs.
    if (pi == 0)  // carrying is pad-1 only (updateUseTarget)
      applyCarryWhisker(P.x, P.z, &nextX, &nextZ, P.y + PP_CAM_HEIGHT(pi),
                        P.yaw, P.y, PP_EYE_HEIGHT(pi));
    portalPassOn = false;
    const float movedX = nextX - P.x, movedZ = nextZ - P.z;
    P.x = nextX;
    P.z = nextZ;

    // Gravity & jumping. velY is units/SECOND - see the note in the
    // single-player walker below; a per-frame velocity makes the jump height
    // depend on how long the frame the button was pressed on happened to be.
    P.velY -= GRAVITY * g_frameDt;
    P.y += P.velY * g_frameDt;
    const float maxY = ceiling - PP_EYE_HEIGHT(pi) - EYE_CLEARANCE;
    if (P.y > maxY && maxY >= ground) {
      P.y = maxY;
      if (P.velY > 0.0F) P.velY = 0.0F;
    }
    bool grounded = false;
    if (P.y <= ground) {
      P.y = ground;
      P.velY = 0.0F;
      grounded = true;
      if (PP_CAN_JUMP(pi) && !g_playerLocked && inputClicked(pad, IA_ROLE_JUMP))
        P.velY = PP_JUMP_SPEED(pi);
    }

    // Turn the avatar (shortest-arc lerp): toward its movement direction, or
    // with face-camera (strafe) locomotion toward the camera yaw - sideways
    // and backward movement then keep the avatar oriented toward the camera
    // and the directional clips play instead of the body swinging around.
    const float movedLen = sqrtf(movedX * movedX + movedZ * movedZ);
    const bool moving = movedLen > 0.0005F;
    if (moving || PP_FACE_CAMERA(pi)) {
      const float desired = PP_FACE_CAMERA(pi) ? P.yaw : atan2f(movedX, movedZ);
      float d = desired - P.faceYaw;
      while (d > PI) d -= 2.0F * PI;
      while (d < -PI) d += 2.0F * PI;
      float k = PP_TURN_RATE(pi) * g_frameScale;
      if (k > 1.0F) k = 1.0F;
      P.faceYaw += d * k;
    }
    // Movement direction in the avatar's own frame (0 = straight ahead,
    // negative = toward the avatar's right - the strafe convention above);
    // drivePlayerAnim picks the strafe/back clips from it.
    float moveLocal = 0.0F;
    if (moving) {
      moveLocal = atan2f(movedX, movedZ) - P.faceYaw;
      while (moveLocal > PI) moveLocal -= 2.0F * PI;
      while (moveLocal < -PI) moveLocal += 2.0F * PI;
    }

    // Camera boom: the eye rides PP_CAM_DIST behind/above the head along
    // the orbit direction. The spring arm shortens the boom to the first thing
    // it hits so the camera never enters geometry or the terrain. Classic
    // spring behavior: pull IN instantly (a late pull-in means a visible clip
    // through a wall) and ease back OUT, so leaving cover doesn't snap.
    const float headY = P.y + PP_CAM_HEIGHT(pi);
    const float cp = cosf(P.pitch);
    const float boomX = sinf(P.yaw) * cp;
    const float boomZ = cosf(P.yaw) * cp;
    const float boomY = sinf(P.pitch);

    // Over-the-shoulder: slide the WHOLE rig - eye and look-at alike - along
    // the camera's right vector, so the avatar sits off-center in frame.
    // (Offsetting only the eye would just angle the camera back at the player
    // and keep them centered - that is not an over-the-shoulder shot.) The
    // right vector matches the walkers' own strafe convention. The offset is
    // itself spring-armed so a shoulder cam cannot slide into a wall the player
    // is hugging - and this second cast costs nothing at all when the offset is
    // 0, which is the default.
    const float rx = -cosf(P.yaw), rz = sinf(P.yaw);
    float shoulder = PP_CAM_SHOULDER(pi);
    if (shoulder > 0.0001F || shoulder < -0.0001F) {
      const float s = shoulder < 0.0F ? -1.0F : 1.0F;
      shoulder = s * springArm(P.x, headY, P.z, rx * s, 0.0F, rz * s,
                               shoulder * s);
    }
    const float pivotX = P.x + rx * shoulder;
    const float pivotZ = P.z + rz * shoulder;

    float want =
        springArm(pivotX, headY, pivotZ, -boomX, -boomY, -boomZ, PP_CAM_DIST(pi));
    if (want < CAM_MIN_DIST) want = CAM_MIN_DIST;

    // Whisker anticipation: two extra casts splayed ~20 deg to either side of
    // the boom spot walls the camera is about to sweep behind and start easing
    // the boom in before the straight ray is blocked. A whisker hit is
    // off-axis - a hint, not the true obstruction - so it only pulls the
    // target partway toward its own distance. The want-clamp below remains the
    // never-clip guarantee; whiskers just mean it usually fires from a boom
    // that is already most of the way in, so the residual jump is small.
    float target = want;
    const float wcos = 0.94F, wsin = 0.342F;
    for (int s = -1; s <= 1; s += 2) {
      const float wx = -boomX * wcos + (-boomZ) * (wsin * s);
      const float wz = boomX * (wsin * s) - boomZ * wcos;
      const float d =
          springArm(pivotX, headY, pivotZ, wx, -boomY, wz, PP_CAM_DIST(pi));
      const float soft = d + (want - d) * 0.4F;
      if (soft < target) target = soft;
    }
    if (target < CAM_MIN_DIST) target = CAM_MIN_DIST;

    // Ease toward the anticipated length: briskly in (a few frames), gently
    // back out (~2 s for a full boom), and never past the straight-ray hit -
    // blocked mid-ease still clamps so the camera cannot enter geometry.
    const float rate = target < P.boom ? 0.30F : 0.06F;
    float k = rate * g_frameScale;
    if (k > 1.0F) k = 1.0F;
    P.boom += (target - P.boom) * k;
    if (P.boom > want) P.boom = want;
    if (P.boom < CAM_MIN_DIST) P.boom = CAM_MIN_DIST;
    float eyeX = pivotX - boomX * P.boom;
    float eyeY = headY - boomY * P.boom;
    float eyeZ = pivotZ - boomZ * P.boom;
    // Safety net: the march samples the heightmap discretely, so a sharp ridge
    // between two samples could still leave the eye underground.
    const float minEyeY = terrainHeightAt(eyeX, eyeZ) + 0.4F;
    if (eyeY < minEyeY) eyeY = minEyeY;
    P.camPos = Vec4(eyeX, eyeY, eyeZ);
    P.camLook = Vec4(pivotX, headY, pivotZ);

    // Drive the avatar object: stand at the feet, face the walk direction,
    // and auto-select its locomotion clip. updateAndRenderAnimObjects draws it.
    if (P.objIndex >= 0 && P.objIndex < (int)runtimeObjects.size()) {
      RuntimeObject& body = runtimeObjects[P.objIndex];
      body.data.position[0] = P.x;
      body.data.position[1] = P.y;
      body.data.position[2] = P.z;
      body.data.rotation[1] = P.faceYaw * 180.0F / PI;
      // Locomotion clips are measured against the RUN speed - the top of the
      // stick ramp - so PP_RUN_THRESHOLD keeps meaning "fraction of full-stick
      // speed" whether or not a run speed was set (with none, RUN == WALK and
      // this is the expression it always was). Sprinting exceeds the run
      // speed, so it still pushes the fraction past the threshold.
      const float step = P.speeds[1] * g_frameScale;
      drivePlayerAnim(P, body, step > 1e-4F ? movedLen / step : 0.0F, grounded,
                      moveLocal, sprinting);
    }
    return;
  }

  // Walk mode: terrain bounds, object collision, gravity + jump.
  float nextX = P.x + (fx * forward - fz * strafe) * moveSpeed * g_frameScale;
  float nextZ = P.z + (fz * forward + fx * strafe) * moveSpeed * g_frameScale;

  const float limX = TERRAIN_WIDTH * 0.5F - 1.0F;
  const float limZ = TERRAIN_DEPTH * 0.5F - 1.0F;
  if (nextX > limX) nextX = limX;
  if (nextX < -limX) nextX = -limX;
  if (nextZ > limZ) nextZ = limZ;
  if (nextZ < -limZ) nextZ = -limZ;

  float ground = walkGroundAt(nextX, nextZ, P.y);
  // a linked floor portal underfoot swallows the walker (see
  // portalSwallowsPlayer) - the terrain stops being the floor there
  if (PORTAL_COUNT > 0 && portalSwallowsPlayer(nextX, P.y, nextZ))
    ground = -1e30F;
  float ceiling = 1e30F;
  // Shove physics bodies with the attempted step first - collidePlayer may
  // cancel the move against the (still solid) body, the push moves it away
  // over the next frames.
  pushPhysicsBodies(P.x, P.z, nextX, nextZ, P.y, PP_EYE_HEIGHT(pi));
  updatePortalPass(nextX, P.y, nextZ);  // wall doorways open in collision
  collidePlayer(P.x, P.z, &nextX, &nextZ, P.y, PP_EYE_HEIGHT(pi), &ground,
                &ceiling);
  // whisker reads portalPassOn (carry through a portal) - reset after it
  if (pi == 0)  // carrying is pad-1 only (updateUseTarget)
    applyCarryWhisker(P.x, P.z, &nextX, &nextZ, P.y + PP_EYE_HEIGHT(pi),
                      P.yaw, P.y, PP_EYE_HEIGHT(pi));
  portalPassOn = false;
  P.x = nextX;
  P.z = nextZ;

  // Gravity & jumping. GRAVITY is units/s^2 and velY is units/SECOND - see
  // the note in the single-player walker below.
  P.velY -= GRAVITY * g_frameDt;
  P.y += P.velY * g_frameDt;
  // Jump clamp: keep the eye EYE_CLEARANCE below overhead geometry so the
  // camera never pokes into it (skipped when the gap is too low to stand in)
  const float maxY = ceiling - PP_EYE_HEIGHT(pi) - EYE_CLEARANCE;
  if (P.y > maxY && maxY >= ground) {
    P.y = maxY;
    if (P.velY > 0.0F) P.velY = 0.0F;
  }
  if (P.y <= ground) {
    P.y = ground;
    P.velY = 0.0F;
    if (PP_CAN_JUMP(pi) && !g_playerLocked && inputClicked(pad, IA_ROLE_JUMP))
      P.velY = PP_JUMP_SPEED(pi);  // units/s
  }

  const float eyeY = P.y + PP_EYE_HEIGHT(pi);
  P.camPos = Vec4(P.x, eyeY, P.z);
  P.camLook = Vec4(P.x + fx * cosf(P.pitch), eyeY + sinf(P.pitch),
                   P.z + fz * cosf(P.pitch));
}



// Shared-screen camera: orbit (P1's right stick, mirrored into both players'
// yaw/pitch by the dispatcher) around the midpoint of the two avatars, with
// the boom stretched by their separation so the pair stays in frame. The
// spring arm and terrain safety net match the single-player boom.
void TerrainGame::updateSharedCamera() {
  PlayerCtl& A = players[0];
  PlayerCtl& B = players[1];
  const float midX = (A.x + B.x) * 0.5F;
  const float midZ = (A.z + B.z) * 0.5F;
  const float midY = (A.y + B.y) * 0.5F + PP_CAM_HEIGHT(0);
  const float dx = A.x - B.x, dy = A.y - B.y, dz = A.z - B.z;
  const float sep = sqrtf(dx * dx + dy * dy + dz * dz);
  const float dist = PP_CAM_DIST(0) + sep * 0.7F;

  const float cp = cosf(A.pitch);
  const float boomX = sinf(A.yaw) * cp;
  const float boomZ = cosf(A.yaw) * cp;
  const float boomY = sinf(A.pitch);

  float want = springArm(midX, midY, midZ, -boomX, -boomY, -boomZ, dist);
  if (want < CAM_MIN_DIST) want = CAM_MIN_DIST;
  if (want < sharedBoom) {
    sharedBoom = want;  // blocked: snap in, never clip
  } else {
    float k = 0.06F * g_frameScale;
    if (k > 1.0F) k = 1.0F;
    sharedBoom += (want - sharedBoom) * k;
  }
  float eyeX = midX - boomX * sharedBoom;
  float eyeY = midY - boomY * sharedBoom;
  float eyeZ = midZ - boomZ * sharedBoom;
  const float minEyeY = terrainHeightAt(eyeX, eyeZ) + 0.4F;
  if (eyeY < minEyeY) eyeY = minEyeY;
  cameraPosition = Vec4(eyeX, eyeY, eyeZ);
  cameraLookAt = Vec4(midX, midY, midZ);
}



// Player 2 join/leave (Start on pad 2, or a menu Toggle bound to "Player
// count"). Guarded: joining needs a two-player mode and a second Player
// object in the scene. Shows/hides the P2 third-person avatar and keeps the
// bound menu row's save value in sync so both entry points agree.
void TerrainGame::setPlayerTwoActive(bool active) {
  if (active && (MULTIPLAYER_MODE == 0 || players[1].objIndex < 0)) return;
  if (playerTwoActive == active) return;
  playerTwoActive = active;
  if (players[1].objIndex >= 0 && PP_MODE(1) == 2 &&
      players[1].objIndex < (int)runtimeObjects.size())
    runtimeObjects[players[1].objIndex].visible = active;
  syncPlayerCountMenuValue();
}



// Locomotion-driven clip selection for the third-person avatar. speedFrac is
// the planar speed as a fraction of full walk speed. The mapping is trivial -
// idle / walk / run by speed, jump while airborne - and the avatar's playback
// speed tracks the real speed so the feet don't slide. The escape hatch: if a
// non-locomotion clip is currently playing (a script or an Animation node
// one-shot), locomotion holds off until it finishes, then resumes. This is the
// whole "third-person for free" story: no state machine, full override.
void TerrainGame::drivePlayerAnim(PlayerCtl& P, RuntimeObject& body,
                                  float speedFrac, bool grounded,
                                  float moveLocal, bool sprinting) {
  if (P.objIndex < 0 || !objectGeometry[P.objIndex].animInst) return;
  const int pi = &P == &players[1] ? 1 : 0;
  body.animPlaying = true;

  int want;
  bool onSprintClip = false;
  if (!grounded && P.jumpClip >= 0)
    want = P.jumpClip;
  else if (speedFrac < 0.12F)
    want = P.idleClip;
  else {
    // Moving: directional family first. Sectors around the facing - within
    // 60 deg of straight ahead = walk/run, within 60 deg of straight back =
    // backpedal, the two side quadrants = sidestep (negative moveLocal is
    // toward the avatar's right). An unmapped direction falls back to walk,
    // so a model with only idle/walk keeps today's behavior exactly.
    const float a = moveLocal < 0.0F ? -moveLocal : moveLocal;
    int dir = -1;
    if (a > 2.0943951F)  // > 120 deg
      dir = P.backClip;
    else if (a > 1.0471976F)  // 60..120 deg
      dir = moveLocal < 0.0F ? P.strafeRClip : P.strafeLClip;
    // Above the run threshold the sprint clip REPLACES the run clip while the
    // sprint action is held - the tier is a button, not a speed band, so it is
    // read from the button. A project with no sprint clip keeps using the run
    // clip for both, exactly as before.
    if (dir >= 0)
      want = dir;
    else if (speedFrac < PP_RUN_THRESHOLD(pi))
      want = P.walkClip;
    else if (sprinting && P.sprintClip >= 0) {
      want = P.sprintClip;
      onSprintClip = true;
    } else if (P.runClip >= 0)
      want = P.runClip;
    else
      want = P.walkClip;
  }
  if (want < 0) want = P.idleClip;
  if (want < 0) want = 0;  // no clips mapped: hold the model's first clip

  const bool locomotion =
      body.animClip == P.idleClip || body.animClip == P.walkClip ||
      body.animClip == P.runClip || body.animClip == P.sprintClip ||
      body.animClip == P.jumpClip ||
      body.animClip == P.backClip || body.animClip == P.strafeLClip ||
      body.animClip == P.strafeRClip;
  if (!locomotion && !body.animFinished) return;  // let a one-shot finish

  if (body.animClip != want) {
    body.animClip = want;
    body.animLoop = true;
    body.animRestart = true;
    body.animFade = 0.18F;  // cross-fade from the outgoing pose
  }
  // Match playback to foot speed on the moving clips (min 0.6x so a slow creep
  // still animates), otherwise the authored speed.
  const float base = body.data.animSpeed;
  if (want != P.idleClip && want != P.jumpClip && speedFrac >= 0.12F) {
    // speedFrac is measured against the RUN speed, so a sprint clip - authored
    // at sprint pace - would be driven at sprint/run times its authored rate
    // and visibly gallop. Normalise it against the tier the clip belongs to,
    // so a sprint clip plays 1x while actually sprinting.
    float frac = speedFrac;
    if (onSprintClip && P.speeds[1] > 1e-6F) {
      const float ratio = P.speeds[2] / P.speeds[1];
      if (ratio > 1e-6F) frac /= ratio;
    }
    body.animSpeed = base * (frac < 0.6F ? 0.6F : frac);
  } else
    body.animSpeed = base;
}



void TerrainGame::buildSkyDome() {
  if (!SKY_DOME) return;

  const float diag = TERRAIN_WIDTH > TERRAIN_DEPTH ? TERRAIN_WIDTH : TERRAIN_DEPTH;
  float radius = diag * 1.5F;
  if (radius < 60.0F) radius = 60.0F;
  if (radius > 450.0F) radius = 450.0F;

  // A painted sky (docs/sky-texture.md) wants more segments than a gradient:
  // the panorama's UVs are linear in longitude and latitude, the dome's faces
  // are flat chords, and 14 slices bend a straight cloud edge visibly.
#ifdef SKY_TEXTURES_ON
  const bool textured = skyTex != nullptr;
#else
  const bool textured = false;
#endif
  const int stacks = textured ? 8 : 6, slices = textured ? 24 : 14;
  // The zenith comes from skyTop*, seeded to the baked SKY_TOP_* and moved by
  // the runtime cycle - so one dome build serves both.
  if (skyTopR < 0.0F) skyTopR = SKY_TOP_R, skyTopG = SKY_TOP_G, skyTopB = SKY_TOP_B;
  auto skyAt = [&](float t) {  // t: 0 = horizon, 1 = zenith
    return Color(skyHorizonR + (skyTopR - skyHorizonR) * t,
                 skyHorizonG + (skyTopG - skyHorizonG) * t,
                 skyHorizonB + (skyTopB - skyHorizonB) * t, 128.0F);
  };
  // On a painted sky the gradient only TINTS: the ratio of the live colour to
  // the one the scene was authored with (128 = the panorama as painted), so
  // the authored hour shows the image untouched while the day/night cycle and
  // Set Sky Color still darken or warm it.
  auto tintAt = [&](float t) {
    const Color live = skyAt(t);
    auto ratio = [](float cur, float ref) {
      const float r = ref > 1.0F ? cur / ref : 1.0F;
      const float c = r * 128.0F;
      return c > 255.0F ? 255.0F : (c < 0.0F ? 0.0F : c);
    };
    return Color(ratio(live.r, SKY_R + (SKY_TOP_R - SKY_R) * t),
                 ratio(live.g, SKY_G + (SKY_TOP_G - SKY_G) * t),
                 ratio(live.b, SKY_B + (SKY_TOP_B - SKY_B) * t), 128.0F);
  };
  auto latOf = [&](int stack) {
    // Start slightly below the horizon so the seam is never visible
    return -0.06F + (PI * 0.5F + 0.06F) * stack / stacks;
  };
  auto domeVert = [&](int stack, int slice) {
    const float lat = latOf(stack);
    const float lon = 2.0F * PI * slice / slices;
    return Vec4(radius * cosf(lat) * cosf(lon), radius * sinf(lat),
                radius * cosf(lat) * sinf(lon), 1.0F);
  };
#ifdef SKY_TEXTURES_ON
  // Twin of skytex::domeUv (src/skytex.hpp) and the viewport's sky mesh.
  auto domeSt = [&](int stack, int slice) {
    const float u = (float)slice / slices + SKY_TEXTURE_YAW / 360.0F;
    const float v = (0.5F - latOf(stack) / PI) / SKY_TEXTURE_VMAX;
    return Vec4(u, v, 1.0F, 0.0F);
  };
#endif

  skyDome.vertices.clear();
  skyDome.colors.clear();
  skyDome.sts.clear();
  for (int st = 0; st < stacks; ++st) {
    // Zenith-size bias: pow(elevation fraction, SKY_ZENITH_EXP). exp 1 = linear.
    const float t0 = powf((float)st / stacks, SKY_ZENITH_EXP),
                t1 = powf((float)(st + 1) / stacks, SKY_ZENITH_EXP);
    const Color c0 = textured ? tintAt(t0) : skyAt(t0);
    const Color c1 = textured ? tintAt(t1) : skyAt(t1);
    for (int sl = 0; sl < slices; ++sl) {
      const Vec4 v00 = domeVert(st, sl), v01 = domeVert(st, sl + 1);
      const Vec4 v10 = domeVert(st + 1, sl), v11 = domeVert(st + 1, sl + 1);
      skyDome.vertices.push_back(v00);
      skyDome.vertices.push_back(v10);
      skyDome.vertices.push_back(v11);
      skyDome.vertices.push_back(v00);
      skyDome.vertices.push_back(v11);
      skyDome.vertices.push_back(v01);
      skyDome.colors.push_back(c0);
      skyDome.colors.push_back(c1);
      skyDome.colors.push_back(c1);
      skyDome.colors.push_back(c0);
      skyDome.colors.push_back(c1);
      skyDome.colors.push_back(c0);
#ifdef SKY_TEXTURES_ON
      if (textured) {
        // Per QUAD corner, not per shared vertex: slice `slices` is u = 1,
        // not 0, which is what keeps the seam from smearing the whole image
        // across one column of triangles.
        skyDome.sts.push_back(domeSt(st, sl));
        skyDome.sts.push_back(domeSt(st + 1, sl));
        skyDome.sts.push_back(domeSt(st + 1, sl + 1));
        skyDome.sts.push_back(domeSt(st, sl));
        skyDome.sts.push_back(domeSt(st + 1, sl + 1));
        skyDome.sts.push_back(domeSt(st, sl + 1));
      }
#endif
    }
  }

  skyDome.infoBag = std::make_unique<StaPipInfoBag>();
  // Not the shared identity `model`: renderScene keeps skyMat centered on the
  // camera so the dome follows the player instead of sitting at world origin.
  skyDome.infoBag->model = &skyMat;
  skyDome.infoBag->shadingType = TyraShadingGouraud;
  // Static geometry crossing the screen edges all the time - needs clipping
  skyDome.infoBag->frustumCulling = PipelineInfoBagFrustumCulling_Precise;
  skyDome.infoBag->fullClipChecks = true;
  // The dome sits past the fog end distance - hardware fog would paint it
  // solid fog color, so it opts out (the horizon still fades into the fog
  // because the terrain and objects do get fogged).
  skyDome.infoBag->fogDisabled = true;
  // The dome is centered on the camera - a nearby dynamic light would win
  // its pick and tint the whole sky.
  skyDome.infoBag->dynLightPick = false;
  // ...and for the same reason it cannot be described to the BLSS upscaler:
  // a shell around the eye has no screen bounding box that means anything.
  // Its package boxes wrap the near plane, so each one reports "the frame,
  // fully covered, at the nearest representable depth" and flattens coverage,
  // depth and depthGrad wherever it lands. Measured: with the dome in, the
  // widest proxy of an `fpp` frame was the top 106 rows of the screen.
  skyDome.infoBag->blssProxy = false;
  skyDome.colorBag = std::make_unique<StaPipColorBag>();
  skyDome.colors.bind(skyDome.colorBag);
  skyDome.bag = std::make_unique<StaPipBag>();
  skyDome.bag->info = skyDome.infoBag.get();
  skyDome.bag->color = skyDome.colorBag.get();
  skyDome.vertices.bind(skyDome.bag);
  skyDome.bag->count = static_cast<u32>(skyDome.vertices.size());
  skyDome.bag->texture = nullptr;
#ifdef SKY_TEXTURES_ON
  if (textured) {
    skyDome.texBag = std::make_unique<StaPipTextureBag>();
    skyDome.texBag->texture = skyTex;
    skyDome.sts.bind(skyDome.texBag);
    skyDome.bag->texture = skyDome.texBag.get();
  }
#endif
  skyDome.bag->lighting = nullptr;
  skyDome.bag->bboxVersion = ++g_bboxStamp;  // dome rebuilds on retint
}



// Coplanar passes over ONE vertex array must split into the SAME VU1 packages.
//
// The engine derives a bag's package size from its VU1 program class: how many
// verts of (position [+ ST] [+ normal] + color) fit in half a VU1 double
// buffer. An untextured bag with per-vertex colors fits 108, a textured one 72.
// So an object whose base pass is untextured and whose companion pass is
// textured - a reflective sphere with no map_Kd, any primitive under the baked
// lightmap - splits the same array at different boundaries. StaPipCore then
// classifies each package against the frustum, and with full clip checks on, a
// package fully inside gets its perspective divide on VU1 while a package
// straddling a plane is clipped on the EE and drawn by an `as_is` program. Two
// routes over the same triangle differ in the last bits of z - and at the
// frustum edge in coverage - which is exactly what a coplanar GEQUAL test
// cannot survive: grey dithered wedges bleeding from under a reflective object,
// baked shadows fighting z-index with the ground they sit on.
//
// Pin them all to the SMALLEST size any of the passes derives. The minimum is
// not a preference: pinning a class above its own capacity overflows its VU1
// buffer. The base pass loses a few verts per package; that is the price.
// (It also un-splits the frustum-bbox cache, which is keyed by package size on
// top of the vertex pointer - the passes now share one entry instead of
// recomputing each other's boxes every frame.)
void TerrainGame::pinPackageSize(const std::vector<Tyra::StaPipBag*>& bags,
                                 u32 stripRun) {
  if (stripRun != 0) {
    // A stripped array is already chopped into self-contained runs of exactly
    // this many vertices, and every pass over it has to split it there - a
    // package boundary anywhere else fuses two strips. Nothing is derived:
    // the run is by construction no larger than any class's own capacity
    // (minPackageSize), so StaPipCore's clamp leaves it alone.
    for (Tyra::StaPipBag* b : bags)
      if (b && b->count != 0) {
        b->packageSize = stripRun;
        b->stripped = true;
      }
    return;
  }
  for (Tyra::StaPipBag* b : bags)
    if (b) b->stripped = false;
  u32 size = 0;
  for (Tyra::StaPipBag* b : bags) {
    if (!b || b->count == 0) continue;
    b->packageSize = 0;  // ask for the DERIVED size, not the last pin
    const u32 s = stapip.core.getMaxVertCountByBag(b);
    if (s != 0 && (size == 0 || s < size)) size = s;
  }
  if (size == 0) return;
  for (Tyra::StaPipBag* b : bags)
    if (b && b->count != 0) b->packageSize = size;
}



// See the declaration. Eight combinations, one of which (lighting with
// per-vertex colours) the engine refuses, so it is skipped.
u32 TerrainGame::minPackageSize() {
  static u32 cached = 0;
  if (cached != 0) return cached;
  for (int single = 0; single < 2; ++single)
    for (int lit = 0; lit < 2; ++lit)
      for (int tex = 0; tex < 2; ++tex) {
        if (lit && !single) continue;
        const u32 v = stapip.core.getMaxVertCountByParams(single != 0, lit != 0,
                                                          tex != 0);
        if (v != 0 && (cached == 0 || v < cached)) cached = v;
      }
  return cached;
}



// ---------------------------------------------------------------------------
// Instance sharing (INSTANCE_SHARING, docs/instance-sharing.md).
//
// A static model instance used to bake its own WORLD-space copy of every
// vertex - position, lit colour and ST, 48 bytes each, per instance. A shared
// instance draws ONE model-space bake of the part (built here, owned by the
// model and every instance through ShRef) under its own objMat, which
// carries position, rotation AND scale, so VU1 applies the transform. What
// stays per instance is the colour, still lit in world space by the same
// shadeVertexColor the solo bake uses - and even that is pooled by content.

// The model-space bake of one part: the topology rebuildObjectGeometry would
// pick for a solo bake (the strip twin when it fits a package), positions with
// w = 1 and the part's own UVs - nothing scaled, rotated or lit.
TerrainGame::ShRef<TerrainGame::SharedGeo> TerrainGame::acquireSharedGeo(
    int model, int pi) {
  if (model < 0 || model >= (int)gameModels.size()) return ShRef<SharedGeo>();
  GameModel& gm = gameModels[model];
  if (pi < 0 || pi >= (int)gm.parts.size()) return ShRef<SharedGeo>();
  if (gm.sharedParts.size() != gm.parts.size())
    gm.sharedParts.resize(gm.parts.size());
  ShRef<SharedGeo>& slot = gm.sharedParts[pi];
  if (slot) return slot;
  const GameModelPart& src = gm.parts[pi];
  const bool useStrip = src.stripRun != 0 && !src.stripVerts.empty() &&
                        src.stripRun <= minPackageSize();
  const std::vector<float>& geo = useStrip ? src.stripVerts : src.verts;
  ShRef<SharedGeo> sg(new SharedGeo());
  // Exact capacity: these arrays live as long as the model, and a doubling
  // vector would carry up to half again as much slack for nothing.
  sg->vertices.reserve(geo.size() / 8);
  sg->sts.reserve(geo.size() / 8);
  for (size_t i = 0; i + 7 < geo.size(); i += 8) {
    const float* v = &geo[i];
    sg->vertices.push_back(Vec4(v[0], v[1], v[2], 1.0F));
    sg->sts.push_back(Vec4(v[6], v[7], 1.0F, 0.0F));
    for (int a = 0; a < 3; ++a) {
      if (i == 0 || v[a] < sg->mn[a]) sg->mn[a] = v[a];
      if (i == 0 || v[a] > sg->mx[a]) sg->mx[a] = v[a];
    }
  }
  sg->stripRun = useStrip ? src.stripRun : 0u;
  sg->stamp = ++g_bboxStamp;
  slot = sg;
  return sg;
}



// Equal colour arrays are ONE array. Lit in world space, a facade's colours
// depend only on its world normals unless a position-dependent term (a GI
// probe, a baked point light, an emissive pool, contact AO) reaches it - so in
// a city of a few rotations most instances of a model come out byte-identical,
// and the comparison below finds that out instead of having to predict it.
// `cols` is consumed when it is adopted.
TerrainGame::ShRef<TerrainGame::SharedColors> TerrainGame::poolColors(
    BagArray<Color>& cols) {
  const size_t words = cols.size() * (sizeof(Color) / sizeof(u32));
  const u32* w = reinterpret_cast<const u32*>(cols.data());
  u32 h = 2166136261u ^ (u32)cols.size();
  for (size_t i = 0; i < words; ++i) {
    h ^= w[i];
    h *= 16777619u;
  }
  std::vector<ShRef<SharedColors>>& bucket = colorPool[h];
  for (size_t k = 0; k < bucket.size();) {
    const ShRef<SharedColors>& sc = bucket[k];
    // The pool's own reference is the last one: nobody draws it any more.
    if (sc.useCount() <= 1) {
      bucket.erase(bucket.begin() + (long)k);
      continue;
    }
    if (sc->colors.size() == cols.size() &&
        memcmp(sc->colors.data(), cols.data(), cols.size() * sizeof(Color)) == 0)
      return sc;
    ++k;
  }
  ShRef<SharedColors> sc(new SharedColors());
  sc->colors.swap(cols);
  sc->hash = h;
  bucket.push_back(sc);
  // An array nobody draws any more (its instances were rebuilt, recoloured or
  // streamed out) is held by the pool alone until its bucket is next visited;
  // sweep the whole pool now and then so a long Live Link session or layer
  // streaming cannot pile those up. `bucket` holds `sc`, so the sweep keeps
  // it.
  if ((++colorPoolAdds & 255U) == 0) pruneColorPool();
  return sc;
}



void TerrainGame::pruneColorPool() {
  for (auto it = colorPool.begin(); it != colorPool.end();) {
    std::vector<ShRef<SharedColors>>& b = it->second;
    for (size_t k = 0; k < b.size();)
      if (b[k].useCount() <= 1)
        b.erase(b.begin() + (long)k);
      else
        ++k;
    if (b.empty())
      it = colorPool.erase(it);
    else
      ++it;
  }
}



// Which objects may draw from the shared bake. Everything else keeps the solo
// world-space bake, and every exclusion is a consumer that cannot work from
// model-space vertices under a matrix (docs/instance-sharing.md, "Who stays
// solo"):
//  - anything that moves or rebuilds per frame (physics, pickables, the matrix
//    path's own users, impostor swaps, VU programs that move geometry);
//  - the USE highlight (hull/apron walk the vertices in world space);
//  - dynamic lighting (its own lit bag and normals), reflective parts (the env
//    pass's per-vertex normals), texture feeds (colours rewritten per object);
//  - a project VU1 program: it sees the vertices before the transform;
//  - NON-UNIFORM scale where a dynamic light can reach: the engine lights a
//    bag in object space with one range per mesh (buildSpotForBag), which is
//    exact under a uniform scale and an ellipse under a stretched one.
bool TerrainGame::instanceShareEligible(int index) const {
  if (!INSTANCE_SHARING) return false;
  if (index < 0 || index >= (int)runtimeObjects.size()) return false;
  const RuntimeObject& o = runtimeObjects[index];
  const ObjectGeometry& g = objectGeometry[index];
  const SceneObjectData& d = o.data;
  if (g.noShare || d.type != 5 || d.animModel >= 0) return false;
  if (d.model < 0 || d.model >= (int)gameModels.size()) return false;
  const GameModel& gm = gameModels[d.model];
  if (gm.parts.empty()) return false;
  if (d.physics || d.usable || d.pickable || o.wantsMatrixPath) return false;
  if (d.dynLit != 0 && SCENE_PROBES != nullptr) return false;
  if (d.impostorDistance > 0.0F && d.impostorModel >= 0) return false;
  if (vuprog::ENABLED || vuscript::movesGeometry()) return false;
  for (const GameModelPart& p : gm.parts)
    if (p.reflTexture) return false;
  for (int fi = 0; fi < OBJECT_FEED_COUNT; ++fi)
    if (OBJECT_FEEDS[fi].scene == currentScene && OBJECT_FEEDS[fi].object == index)
      return false;
  float smin = d.scale[0], smax = d.scale[0];
  for (int a = 1; a < 3; ++a) {
    if (d.scale[a] < smin) smin = d.scale[a];
    if (d.scale[a] > smax) smax = d.scale[a];
  }
  // A zero or mirrored scale is left to the solo bake: nothing to gain, and a
  // negative determinant is one more thing a matrix would have to get right.
  if (smin <= 0.0F) return false;
  if (smax - smin > 1e-4F * smax) {
    if (FLASHLIGHT_ENABLED) return false;
    const float ex = fmaxf(fabsf(gm.mn[0]), fabsf(gm.mx[0])) * d.scale[0];
    const float ey = fmaxf(fabsf(gm.mn[1]), fabsf(gm.mx[1])) * d.scale[1];
    const float ez = fmaxf(fabsf(gm.mn[2]), fabsf(gm.mx[2])) * d.scale[2];
    const float rad = sqrtf(ex * ex + ey * ey + ez * ez);
    for (const DynLightRt& dl : g_dynLights) {
      const SceneObjectData& L = SCENE_OBJECTS[dl.objIndex];
      const float dx = L.position[0] - d.position[0];
      const float dy = L.position[1] - d.position[1];
      const float dz = L.position[2] - d.position[2];
      const float reach = (L.lightRadius > 0.0F ? L.lightRadius : 0.0F) + rad;
      if (dx * dx + dy * dy + dz * dz <= reach * reach) return false;
    }
  }
  return true;
}



// The colour half of a shared instance: every vertex of the shared bake lit
// in WORLD space - transformed on the fly exactly as pushVert transforms it,
// never stored - with the shading globals rebuildObjectGeometry staged.
// Byte-identical to the solo bake's colours, because it is the same function
// over the same numbers.
void TerrainGame::bakeSharedObject(int index, const GameModel& gm) {
  ObjectGeometry& g = objectGeometry[index];
  const SceneObjectData& d = runtimeObjects[index].data;
  static BagArray<Color> scratch;
  for (int pi = 0; pi < (int)g.parts.size() && pi < (int)gm.parts.size(); ++pi) {
    GeoPart& part = g.parts[pi];
    const GameModelPart& src = gm.parts[pi];
    ShRef<SharedGeo> sg = acquireSharedGeo(d.model, pi);
    if (!sg) continue;
    const bool useStrip = sg->stripRun != 0;
    const std::vector<float>& geo = useStrip ? src.stripVerts : src.verts;
    const std::vector<unsigned char>& geoAo =
        useStrip ? src.stripVertexAo : src.vertexAo;
    const bool hasAo = geoAo.size() * 8 == geo.size();
    const bool textured = src.texture != nullptr;
    scratch.clear();
    scratch.reserve(geo.size() / 8);
    for (size_t i = 0; i + 7 < geo.size(); i += 8) {
      const float* v = &geo[i];
      V3 p = {v[0], v[1], v[2]};
      p.x *= d.scale[0], p.y *= d.scale[1], p.z *= d.scale[2];
      p = rotated(p, d.rotation);
      const V3 n = rotated(V3{v[3], v[4], v[5]}, d.rotation);
      const V3 wp = {p.x + d.position[0], p.y + d.position[1],
                     p.z + d.position[2]};
      scratch.push_back(shadeVertexColor(
          d, wp, n, v[6], v[7], src.kd, src.ke, textured,
          hasAo ? geoAo[i / 8] : (unsigned char)255));
    }
    part.shared = sg;
    part.sharedCols = poolColors(scratch);
    part.stripRun = sg->stripRun;
  }
}



void TerrainGame::unshareObject(int index) {
  if (index < 0 || index >= (int)objectGeometry.size()) return;
  ObjectGeometry& g = objectGeometry[index];
  if (!g.shared) return;
  g.noShare = true;
  // The rebuild consumes `dirty`, which renderStaticBatches keys a batched
  // member's demotion on - hand it back untouched.
  RuntimeObject& o = runtimeObjects[index];
  const bool dirty = o.dirty;
  rebuildObjectGeometry(index);
  o.dirty = dirty;
}



// MEMSTAT (debug builds with the HUD's MEM line on): where object geometry's
// EE RAM goes, a few seconds after a scene load - by then every resident
// object and batch has baked. Capacities, not sizes: slack is RAM too. Read it
// beside the HUD's MEM: `used` is the same number at 1 KB resolution.
void TerrainGame::logGeometryMemory() {
  auto kb = [](size_t b) { return (int)((b + 512) / 1024); };
  size_t tables = runtimeObjects.capacity() * sizeof(RuntimeObject) +
                  objectGeometry.capacity() * sizeof(ObjectGeometry);
  const size_t bagBytes = sizeof(StaPipBag) + sizeof(StaPipInfoBag) +
                          sizeof(StaPipColorBag) + sizeof(StaPipTextureBag);
  size_t soloBytes = 0, soloVerts = 0, partBytes = 0;
  int soloParts = 0, sharedParts = 0, sharedObjects = 0, soloObjects = 0;
  for (const ObjectGeometry& g : objectGeometry) {
    if (g.parts.empty()) continue;
    if (g.shared) ++sharedObjects; else ++soloObjects;
    partBytes += g.parts.capacity() * sizeof(GeoPart);
    for (const GeoPart& p : g.parts) {
      if (p.bag) partBytes += bagBytes;
      if (p.shared) { ++sharedParts; continue; }
      ++soloParts;
      soloVerts += p.vertices.size();
      soloBytes += p.vertices.capacity() * sizeof(Vec4) +
                   p.sts.capacity() * sizeof(Vec4) +
                   p.colors.capacity() * sizeof(Color) +
                   p.envNormals.capacity() * sizeof(Vec4) +
                   p.envColors.capacity() * sizeof(Color) +
                   p.litNormals.capacity() * sizeof(Vec4) +
                   p.aoSts.capacity() * sizeof(Vec4) +
                   p.aoCols.capacity() * sizeof(Color) +
                   p.emisCols.capacity() * sizeof(Color);
      for (const GeoPart::Lod& l : p.lods)
        soloBytes += l.vertices.capacity() * sizeof(Vec4) +
                     l.sts.capacity() * sizeof(Vec4) +
                     l.colors.capacity() * sizeof(Color) +
                     l.envNormals.capacity() * sizeof(Vec4) +
                     l.envColors.capacity() * sizeof(Color);
    }
  }
  size_t colorBytes = 0;
  int colorArrays = 0;
  for (const auto& bucket : colorPool)
    for (const ShRef<SharedColors>& sc : bucket.second)
      if (sc.useCount() > 1) {
        colorBytes += sc->colors.capacity() * sizeof(Color);
        ++colorArrays;
      }
  size_t sharedGeoBytes = 0, sourceBytes = 0;
  for (const GameModel& gm : gameModels) {
    for (const ShRef<SharedGeo>& sg : gm.sharedParts) {
      if (!sg) continue;
      sharedGeoBytes += (sg->vertices.capacity() + sg->sts.capacity()) * sizeof(Vec4);
      for (const SharedGeo::Tier& t : sg->tiers)
        sharedGeoBytes += (t.vertices.capacity() + t.sts.capacity()) * sizeof(Vec4);
    }
    for (const GameModelPart& p : gm.parts) {
      sourceBytes += (p.verts.capacity() + p.stripVerts.capacity()) * sizeof(float);
      for (const std::vector<float>& l : p.lodVerts) sourceBytes += l.capacity() * sizeof(float);
    }
  }
  size_t batchBytes = 0, batchVerts = 0;
  for (const StaticBatch& b : staticBatches) {
    batchVerts += b.vertices.size();
    batchBytes += (b.vertices.capacity() + b.sts.capacity()) * sizeof(Vec4) +
                  b.colors.capacity() * sizeof(Color);
  }
  const int usedKB = (int)((32.0F - engine->info.getAvailableRAM()) * 1024.0F);
  TYRA_LOG("MEMSTAT used ", usedKB, " KB | object tables ", kb(tables),
           " KB | parts+bags ", kb(partBytes), " KB | solo ", soloObjects,
           " objects ", soloParts, " parts ", (int)soloVerts, " verts ",
           kb(soloBytes), " KB | shared ", sharedObjects, " objects ",
           sharedParts, " parts, geometry ", kb(sharedGeoBytes),
           " KB, colours ", colorArrays, " arrays ", kb(colorBytes),
           " KB | batches ", (int)staticBatches.size(), " ", (int)batchVerts,
           " verts ", kb(batchBytes), " KB | model sources ", kb(sourceBytes),
           " KB | engine baked ", kb(stapip.core.getBakedStreamBytes()),
           " KB retained ", kb(stapip.core.getRetainedCommandBytes()), " KB");
}



// rebuildObjectGeometry's staging for an imported model, for the LOD tier
// bakes in applyGeoLod. Those used to inherit whatever the LAST rebuild left
// in the globals - the analytic-light lists of another object, its pre-lit
// flag - so a tier could light differently from its own tier 0.
void TerrainGame::stageModelShading(int index) {
  const SceneObjectData& d = runtimeObjects[index].data;
  float rad = 0.87F * sqrtf(d.scale[0] * d.scale[0] + d.scale[1] * d.scale[1] +
                            d.scale[2] * d.scale[2]);
  if (d.model >= 0 && d.model < (int)gameModels.size()) {
    const GameModel& gm = gameModels[d.model];
    const float ex =
        (fabsf(gm.mn[0]) > fabsf(gm.mx[0]) ? fabsf(gm.mn[0]) : fabsf(gm.mx[0])) * fabsf(d.scale[0]);
    const float ey =
        (fabsf(gm.mn[1]) > fabsf(gm.mx[1]) ? fabsf(gm.mn[1]) : fabsf(gm.mx[1])) * fabsf(d.scale[1]);
    const float ez =
        (fabsf(gm.mn[2]) > fabsf(gm.mx[2]) ? fabsf(gm.mn[2]) : fabsf(gm.mx[2])) * fabsf(d.scale[2]);
    rad = sqrtf(ex * ex + ey * ey + ez * ez);
  }
  const int self = index < SCENE_OBJECT_COUNT ? index : -1;
  aoCollectLocal(d.position[0], d.position[1], d.position[2], rad, self);
  emisCollectLocal(d.position[0], d.position[1], d.position[2], rad, self);
  g_aoAtlas = false;
  g_emisAtlas = false;
  g_aoSts = nullptr;
  g_aoOff = true;  // imported models get no receive/self AO
  g_giLightmap = false;
  g_prelitTex = d.prelit != 0;
  g_giProbeShade = !g_prelitTex && SCENE_PROBES != nullptr &&
                   !(d.dynLit != 0);
  g_primKd = nullptr;
  g_primKe = nullptr;
  g_primTextured = false;
  g_primUvRect = nullptr;
  g_litNormals = nullptr;
  g_envNormals = nullptr;
}

void TerrainGame::resetModelShading() {
  g_aoOff = false;
  g_prelitTex = false;
  g_giProbeShade = false;
  g_envNormals = nullptr;
  g_bakeLocal = false;
}



void TerrainGame::rebuildObjectGeometry(int index, bool localSpace) {
  RuntimeObject& o = runtimeObjects[index];
  ObjectGeometry& g = objectGeometry[index];
  o.dirty = false;
  g.coarseBoxValid = false;
  g.reflectionProxy.reset();
  g.matrixMode = localSpace;
  g.shared = false;  // re-decided below, once the model is known
  o.onMatrixPath = localSpace;  // the Script-visible mirror; see RuntimeObject
  g_bakeLocal = localSpace;
  if (localSpace) updateObjMat(index);
  g.apronVerts.clear();  // position/size changed - the highlight ring follows
  g.hullProxyVerts.clear();  // and the shell proxy re-bakes the transform

  // Invisible walls stay active/visible for collision, but submit no geometry
  // to any camera, portal, reflection or shadow pass.
  if (o.data.collision == 3) {
    g.parts.clear();
    g.outlineVerts.clear();
    return;
  }

  // models: one draw part per MTL material; everything else fills parts[0]
  const GameModel* gm = nullptr;
  if (o.data.type == 5 && o.data.model >= 0 &&
      o.data.model < (int)gameModels.size())
    gm = &gameModels[o.data.model];
  if (!g.impostorInitialized) {
    g.impostorInitialized = true;
    const float dx = o.data.position[0] - cameraPosition.x;
    const float dy = o.data.position[1] - cameraPosition.y;
    const float dz = o.data.position[2] - cameraPosition.z;
    g.impostor = !localSpace && !o.data.physics && billboardTransformValid(o.data) && o.data.impostorDistance > 0 &&
        dx*dx + dy*dy + dz*dz > o.data.impostorDistance*o.data.impostorDistance;
  }
  if (localSpace || !billboardTransformValid(o.data)) g.impostor = false;
  if (g.impostor && o.data.impostorModel >= 0 &&
      o.data.impostorModel < (int)gameModels.size() &&
      !gameModels[o.data.impostorModel].parts.empty() &&
      (!o.data.impostorBillboard || gameModels[o.data.impostorModel].parts.size() == (size_t)o.data.impostorViews))
    gm = &gameModels[o.data.impostorModel];
  else
    g.impostor = false;
  const bool billboard = g.impostor && o.data.impostorBillboard;
  if (billboard) g.impostorView = billboardView(o.data, cameraPosition);
  const SceneObjectData visualData = billboard ? billboardTransform(o.data, cameraPosition) : o.data;
  const int partCount = billboard ? 1 : (o.data.type == 5 ? (gm ? (int)gm->parts.size() : 0) : 1);
  if ((int)g.parts.size() != partCount) g.parts.resize(partCount);
  // Instance sharing (bakeSharedObject): re-decided on every rebuild, because
  // an edit can make an object eligible or not. Never the physics fast path
  // or an impostor - those own their vertices.
  g.shared = !localSpace && !billboard && !g.impostor && gm &&
             instanceShareEligible(index);
  if (g.shared) updateObjMat(index);  // scale included - see updateObjMat

  for (int pi = 0; pi < partCount; ++pi) {
    GeoPart& part = g.parts[pi];
    part.stripRun = 0;  // re-decided per rebuild, with the geometry
    part.shared.reset();
    part.sharedCols.reset();
    part.vertices.clear();
    part.colors.clear();
    part.sts.clear();
    part.envNormals.clear();
    // Every resident LOD tier baked the OLD transform/shading - drop them all
    // (a moved, recolored or Live-Link-patched object must not keep stale
    // distant copies) and go back to showing the full mesh.
    part.lods.clear();
    part.shownLod = 0;
  }

  // primitives: the assigned material (first entry of its .mtl) supplies
  // the surface color/texture - staged for the builders via g_prim*
  const GameMaterial* gmat = nullptr;
  if (o.data.type != 5 && o.data.material >= 0 &&
      o.data.material < (int)gameMaterials.size())
    gmat = &gameMaterials[o.data.material];

  // Ambient occlusion: prune the scene occluder table around this object
  // once (pushVert then only loops the handful in range). Authored objects
  // exclude their own occluder; spawned clones (index past the authored
  // count) exclude nothing.
  {
    float aoRad;
    const float sx = o.data.scale[0], sy = o.data.scale[1], sz = o.data.scale[2];
    if (o.data.type == 5 && gm) {
      const float ex =
          (fabsf(gm->mn[0]) > fabsf(gm->mx[0]) ? fabsf(gm->mn[0]) : fabsf(gm->mx[0])) * fabsf(sx);
      const float ey =
          (fabsf(gm->mn[1]) > fabsf(gm->mx[1]) ? fabsf(gm->mn[1]) : fabsf(gm->mx[1])) * fabsf(sy);
      const float ez =
          (fabsf(gm->mn[2]) > fabsf(gm->mx[2]) ? fabsf(gm->mn[2]) : fabsf(gm->mx[2])) * fabsf(sz);
      aoRad = sqrtf(ex * ex + ey * ey + ez * ez);
    } else {
      aoRad = 0.87F * sqrtf(sx * sx + sy * sy + sz * sz);  // unit primitives
    }
    aoCollectLocal(o.data.position[0], o.data.position[1], o.data.position[2],
                   aoRad, index < SCENE_OBJECT_COUNT ? index : -1);
    // Emissive lights use the same bounding sphere and the same
    // once-per-object pruning (see emisCollectLocal).
    emisCollectLocal(o.data.position[0], o.data.position[1], o.data.position[2],
                     aoRad, index < SCENE_OBJECT_COUNT ? index : -1);
  }

  // Authored primitives with an atlas region sample the scene lightmap per
  // pixel - BOTH the ambient occlusion and the baked emissive light, which is
  // why the region exists whenever either has content (the vertex bake shows
  // a strong light gradient as the diagonal seam of every two-triangle face).
  // Spawned clones and physics bodies (FIRST is -1 / index past the authored
  // count) keep the per-vertex bake. Imported models get NO receive/self AO
  // for now (g_aoOff): per-vertex occlusion on authored meshes reads as
  // triangulated shading (owner call, 2026-07) - a proper fix needs a
  // per-model lightmap unwrap. The .aov sidecar plumbing (aobake::modelAO +
  // LeanObjLoader) stays for that future path.
  g_aoAtlas = false;
  g_emisAtlas = false;
  g_aoSts = nullptr;
  g_aoOff = o.data.type == 5;
  if (partCount > 0) g.parts[0].aoSts.clear();
  if (o.data.type != 5 && index < SCENE_OBJECT_COUNT &&
      SCENE_AO_ATLAS_FIRST && SCENE_AO_ATLAS_RECTS &&
      SCENE_AO_ATLAS_FIRST[index] >= 0) {
    g_aoAtlas = true;
    g_emisAtlas = SCENE_AO_ATLAS_LIT && SCENE_AO_ATLAS_LIT[index] != 0;
    g_aoAtlasRects = &SCENE_AO_ATLAS_RECTS[SCENE_AO_ATLAS_FIRST[index]];
    g_aoSts = &g.parts[0].aoSts;
  }
  // Global illumination: the lightmap covers this object when its atlas light
  // channel is a GI channel; everything else the grid reaches - imported
  // models, textured receivers, physics bodies, spawned clones - takes the
  // probe path. Never both (docs/global-illumination.md).
  g_giLightmap = SCENE_AO_ATLAS_GI && g_emisAtlas;
  g_giProbeShade = !g_giLightmap && SCENE_PROBES != nullptr;
  // ...unless the object's TEXTURE already carries its light
  // (docs/prelit-models.md). Then nothing may be baked into its vertices at
  // all: every term below - ambient, N.L, the baked point lights, the emissive
  // pools - is already in the albedo, per pixel, and adding it again lights the
  // surface twice. This is the only per-pixel static light a TEXTURED surface
  // can have on this hardware, so the flag has to beat both routes above.
  g_prelitTex = o.data.prelit != 0;
  if (g_prelitTex) {
    g_giLightmap = false;
    g_giProbeShade = false;
  }
  // Dynamic lighting wins over both: VU1 lights this object from a bag the
  // frame loop refills, so nothing may be baked into its vertices at all.
  // Needs a probe grid to read - without one there is nothing to be dynamic
  // ABOUT, and the object keeps the ordinary baked path.
  const bool dynLit = o.data.dynLit != 0 && SCENE_PROBES != nullptr;
  bool needsLitSeed = false;
  if (dynLit) {
    g_giLightmap = false;
    g_giProbeShade = false;
    // The normal capture is PER PART. A model draws one bag per MTL part and
    // each bag carries its own normal array, so pointing the capture at part 0
    // for the whole object piles every part's normals into part 0: the
    // size == vertices check below then fails for every part, no part gets a
    // lit bag, and the object renders at the white albedo pushVert already
    // wrote. Staged inside the loops instead.
    for (GeoPart& part : g.parts) part.litNormals.clear();
  }

  if (o.data.type == 5 && g.shared) {
    bakeSharedObject(index, *gm);
  } else if (o.data.type == 5) {
    for (int pi = 0; pi < partCount; ++pi) {
      const GameModelPart& src = gm->parts[billboard ? g.impostorView : pi];
      GeoPart& part = g.parts[pi];
      const bool textured = src.texture != nullptr;
      // TRIANGLE STRIPS (docs/model-pipeline.md). The bake stores the strip
      // beside the list, so the shading pass below does not care which it is
      // walking - it is per VERTEX, not per triangle, and the strip's joins
      // and padding are ordinary duplicated vertices. An impostor billboard
      // keeps the list: its part is one of eight captured quads chosen per
      // frame, and nothing about it is worth a strip.
      const bool useStrip = !billboard && src.stripRun != 0 &&
                            !src.stripVerts.empty() &&
                            src.stripRun <= minPackageSize();
      const std::vector<float>& geo = useStrip ? src.stripVerts : src.verts;
      part.stripRun = useStrip ? src.stripRun : 0u;
      // Baked raycast self-AO from the model's .aov sidecar (LeanObjLoader);
      // parallel to the vertex array, one byte per vertex.
      const std::vector<unsigned char>& geoAo =
          useStrip ? src.stripVertexAo : src.vertexAo;
      const bool hasAo = geoAo.size() * 8 == geo.size();
      g_litNormals = dynLit ? &part.litNormals : nullptr;
      g_envNormals = src.reflTexture ? &part.envNormals : nullptr;
      // Exact capacity up front: a push_back-grown vector carries up to as
      // much slack again as it holds, and a solo bake keeps it for life.
      part.vertices.reserve(geo.size() / 8);
      part.colors.reserve(geo.size() / 8);
      part.sts.reserve(geo.size() / 8);
      if (g_litNormals) g_litNormals->reserve(geo.size() / 8);
      if (g_envNormals) g_envNormals->reserve(geo.size() / 8);
      for (size_t i = 0; i + 7 < geo.size(); i += 8) {
        const float* v = &geo[i];
        pushVert(part.vertices, part.colors, part.sts, visualData,
                 {v[0], v[1], v[2]}, billboard ? V3{0,1,0} : V3{v[3], v[4], v[5]}, v[6], v[7], src.kd,
                 textured, hasAo ? geoAo[i / 8] : (unsigned char)255,
                 src.ke);
      }
    }
    g_envNormals = nullptr;
  } else {
    // Primitives, decals and every other builder emit triangle lists.
    for (GeoPart& part : g.parts) part.stripRun = 0;
    g_primKd = gmat ? gmat->kd : nullptr;
    g_primKe = gmat ? gmat->ke : nullptr;
    g_primTextured = gmat && gmat->texture;
    g_primUvRect = g_primTextured ? gmat->uvRect : nullptr;
    g_envNormals =
        (gmat && gmat->reflTexture) ? &g.parts[0].envNormals : nullptr;
    GeoPart& p0 = g.parts[0];
    g_litNormals = dynLit ? &p0.litNormals : nullptr;
    switch (o.data.type) {
      case 1: addSphere(p0.vertices, p0.colors, p0.sts, o.data); break;
      case 2: addCylinder(p0.vertices, p0.colors, p0.sts, o.data); break;
      case 3: addCone(p0.vertices, p0.colors, p0.sts, o.data); break;
      case 4: break;   // spawn point - marker only
      case 6: break;   // player - marker only
      case 7: break;   // emitter - particles are built by updateParticles()
      case 8: break;   // sound emitter - marker only, no geometry
      case 9: break;   // point light - invisible source, no geometry
      case 11: break;  // empty - pure transform, no geometry
      case 17:
        // area - an invisible volume; the debug preference draws its edges
        // (DEBUG_SHOW_AREAS is a constexpr, so a shipping build emits nothing)
        if (DEBUG_SHOW_AREAS)
          addAreaWireframe(p0.vertices, p0.colors, p0.sts, o.data);
        break;
      case 18: break;  // scatter volume - editor authoring region only
      case 20: break;  // comment - an editor note, invisible here
      case 22: break;  // road - buildRoads tessellates it into procChunks
      case 12: addPlane(p0.vertices, p0.colors, p0.sts, o.data); break;
      case 13: {
        // Projecting decal: a world-space mesh conforming to the receiver
        // geometry was baked on the host (decalproj) - just upload it (unlit,
        // tinted; alpha comes from the texture like the flat decal). Falls back
        // to the flat quad when this object has no baked mesh. index maps 1:1 to
        // the scene table for authored objects (spawned clones are past the
        // count, so they never match and use the flat quad).
        const BakedDecal* dt =
            (currentScene >= 0 &&
             currentScene < (int)(sizeof(SCENE_DECAL_TABLES) / sizeof(SCENE_DECAL_TABLES[0])))
                ? SCENE_DECAL_TABLES[currentScene]
                : nullptr;
        if (dt && index < SCENE_DECAL_COUNTS[currentScene] && dt[index].vertCount > 0) {
          const float cs = g_primTextured ? 128.0F : 255.0F;
          const Color col(o.data.color[0] * cs, o.data.color[1] * cs,
                          o.data.color[2] * cs, 128.0F);
          const float* bv = dt[index].verts;
          for (int i = 0; i < dt[index].vertCount; ++i) {
            const float* v = &bv[i * 5];
            p0.vertices.push_back(Vec4(v[0], v[1], v[2], 1.0F));
            p0.colors.push_back(col);
            p0.sts.push_back(Vec4(v[3], v[4], 1.0F, 0.0F));
          }
        } else {
          addDecal(p0.vertices, p0.colors, p0.sts, o.data);
        }
        break;
      }
      case 14: break;  // camera - cutscene shot marker, no geometry
      case 15: {
        // mirror: only the glass quad is geometry (the reflected copies are
        // re-submitted per frame by renderMirrors). Reuses the decal quad
        // (+Z face, slight +Z nudge keeps it off a backing wall), then
        // rewrites the vertex alpha with the authored glass opacity - the
        // GS alpha-blends it over the copies drawn just before it.
        addDecal(p0.vertices, p0.colors, p0.sts, o.data);
        float opacity = 0.35F;
        bool rt = false;
        for (int mi = 0; mi < MIRROR_COUNT; ++mi)
          if (MIRRORS[mi].scene == currentScene && MIRRORS[mi].object == index) {
            opacity = MIRRORS[mi].opacity;
            rt = MIRRORS[mi].raytraced != 0;
            break;
          }
        if (rt) {
          // VU0-raytraced glass: the traced image IS the reflection - draw
          // the quad opaque, full-bright white so the texture (bound in the
          // tail below) shows unmodulated.
          for (Color& c : p0.colors) c.r = c.g = c.b = c.a = 128.0F;
        } else {
          for (Color& c : p0.colors) c.a = opacity * 128.0F;
        }
        break;
      }
      case 16: {
        // portal: the tinted "energy surface" quad (decal quad, +Z face,
        // same +Z nudge). The live through-view is projected over it by
        // renderPortals; on unlinked/far portals - and on the pair member
        // that lost this frame's single view slot - this tint is what shows.
        addDecal(p0.vertices, p0.colors, p0.sts, o.data);
        for (Color& c : p0.colors) c.a = 70.0F;  // ~55% energy-glass alpha
        break;
      }
      case 19: break;  // scroller - invisible belt marker (drives clones)
      default: addBox(p0.vertices, p0.colors, p0.sts, o.data); break;
    }
    g_primKd = nullptr;
    g_primKe = nullptr;
    g_primTextured = false;
    g_envNormals = nullptr;
  }
  g_bakeLocal = false;
  g_aoAtlas = false;
  g_emisAtlas = false;
  g_aoSts = nullptr;
  g_aoOff = false;
  g_giLightmap = false;
  g_giProbeShade = false;
  g_litNormals = nullptr;

  for (int pi = 0; pi < partCount; ++pi) {
    GeoPart& part = g.parts[pi];
    const bool sharedPart = part.shared && part.sharedCols;
    if (sharedPart ? part.shared->vertices.empty() : part.vertices.empty()) {
      part.bag.reset();
      continue;
    }
    if (!part.bag) {
      part.infoBag = std::make_unique<StaPipInfoBag>();
      part.infoBag->model = &model;
      part.infoBag->shadingType = TyraShadingGouraud;
      // Objects go through frustum classification too - raw submission (None)
      // wraps the GS raster window for anything behind/off-screen. The bbox
      // cache is keyed by pointer + bboxVersion, bumped on every rebuild, so
      // moving objects never reuse a stale box.
      part.infoBag->frustumCulling = PipelineInfoBagFrustumCulling_Precise;
      part.infoBag->fullClipChecks = true;  // refreshed below, per frame
      part.colorBag = std::make_unique<StaPipColorBag>();
      part.bag = std::make_unique<StaPipBag>();
      part.bag->info = part.infoBag.get();
      part.bag->color = part.colorBag.get();
      part.bag->texture = nullptr;
      part.bag->lighting = nullptr;
    }
    // OFF while a script displaces vertices AND the EE clipper is the one
    // cutting. That clipper runs before any VU program sees the mesh, so a
    // vertex moved afterwards is moved past a cut computed without it and the
    // prop tears at the edge of the screen; the whole-mesh cull path is the
    // way out, safe for a prop and NOT done for the terrain or the sky.
    //
    // Under VU1 CLIPPING there is nothing to compensate for: the clip program
    // does its own MVP multiply, so the script displaces the vertex BEFORE the
    // cut is computed and the clipper sees the final geometry. Set per frame
    // rather than at bag creation because the mode is a run-time switch.
    part.infoBag->fullClipChecks =
        !vuscript::movesGeometry() || vuprog::vu1Clipping();
    if (sharedPart) {
      // The model's one bake, and its ONE stamp: the frustum-bbox cache is
      // keyed by (vertex pointer, bboxVersion), so every instance of the part
      // shares a single set of model-space package boxes, classified per
      // instance against planes moved into its object space.
      part.sharedCols->colors.bind(part.colorBag);
      part.shared->vertices.bind(part.bag);
      part.bag->count = static_cast<u32>(part.shared->vertices.size());
      part.baseStamp = part.shared->stamp;
    } else {
      part.colors.bind(part.colorBag);
      part.vertices.bind(part.bag);
      part.bag->count = static_cast<u32>(part.vertices.size());
      part.baseStamp = ++g_bboxStamp;         // geometry changed - fresh boxes
    }
    part.bag->bboxVersion = part.baseStamp;
    // Fast-path bodies and shared instances render local vertices under
    // objMat; everything else sits in world space under the shared identity.
    // Reset on every rebuild (the bag may have been created under the other
    // mode).
    part.infoBag->model = (g.matrixMode || g.shared) ? &g.objMat : &model;

    // models: the part's own map_Kd; primitives: the assigned material's
    Texture* tex =
        o.data.type == 5 ? gm->parts[billboard ? g.impostorView : pi].texture : (gmat ? gmat->texture : nullptr);
    // Raytraced mirror: the glass samples the VU0-traced reflection image
    // (created by buildRtMirrors before this rebuild ever runs).
    if (o.data.type == 15)
      for (RtMirror& r : rtMirrors)
        if (r.object == index) { tex = r.texture; break; }
    // Live texture feed: the camera feed target or a raytraced mirror's
    // traced image replaces the surface texture; colors flatten to the
    // object tint at texture scale (128 = 1.0) so the feed reads like an
    // emissive screen instead of inheriting baked shading.
    for (int fi = 0; fi < OBJECT_FEED_COUNT; ++fi) {
      const ObjectFeedData& fd = OBJECT_FEEDS[fi];
      if (fd.scene != currentScene || fd.object != index) continue;
      Texture* ftex = nullptr;
      if (fd.kind == 0)
        ftex = engine->renderer.core.camFeed.getTexture();
      else
        for (RtMirror& r : rtMirrors)
          if (r.object == fd.src) { ftex = r.texture; break; }
      if (ftex) {
        tex = ftex;
        auto c128 = [](float v) {
          return v * 128.0F > 255.0F ? 255.0F : v * 128.0F;
        };
        for (Color& c : part.colors) {
          c.r = c128(o.data.color[0]);
          c.g = c128(o.data.color[1]);
          c.b = c128(o.data.color[2]);
          c.a = 128.0F;
        }
        // The camera feed is a raster render target: GS rows run top-down
        // while texture V grows downward from row 0, so the image samples
        // upside down through plain surface UVs - flip V here (fresh sts
        // every rebuild, so the flip never double-applies). The mirror
        // feed is a RAM texture with its own consistent mapping.
        if (fd.kind == 0)
          for (Vec4& st : part.sts) st.y = 1.0F - st.y;
      }
      break;
    }
    if (tex) {
      if (!part.texBag) part.texBag = std::make_unique<StaPipTextureBag>();
      part.texBag->texture = tex;
      if (sharedPart)
        part.shared->sts.bind(part.texBag);
      else
        part.sts.bind(part.texBag);
      part.bag->texture = part.texBag.get();
    } else {
      part.bag->texture = nullptr;
    }

    // Reflective material (refl): the additive sphere-map second pass. The
    // env bag reuses this part's vertex array and bboxVersion; all-white
    // "many" colors keep its VU1 program shape identical to a textured base
    // bag, so the frustum-bbox cache entry is shared, not recomputed.
    Texture* envTex = o.data.type == 5 ? gm->parts[billboard ? g.impostorView : pi].reflTexture
                                       : (gmat ? gmat->reflTexture : nullptr);
    const float envStr = o.data.type == 5
                             ? gm->parts[billboard ? g.impostorView : pi].reflStrength
                             : (gmat ? gmat->reflStrength : 0.0F);
    if (envTex && envStr > 0.004F &&
        part.envNormals.size() == part.vertices.size()) {
      part.envColors.assign(part.vertices.size(),
                            Color(128.0F, 128.0F, 128.0F, 128.0F));
      // Those are placeholders, not paint: a vehicle's fresnel/specular pass
      // must rewrite them on the next draw. A rebuild that REUSES the part (a
      // repair, a damage re-bake) kept envPaintValid and the old paint key, so
      // the pass saw "same view" and left the car at full reflection until
      // the camera turned four steps - "the car goes very bright after a
      // repair until I drive a bit".
      part.envPaintValid = false;
      part.paintMapSrc = nullptr;
      if (!part.envBag) {
        part.envInfoBag = std::make_unique<StaPipInfoBag>();
        // GOURAUD, not flat: the vehicle paint pass writes a per-vertex
        // fresnel factor into RGB and its specular into A (renderEnvPass),
        // and a flat triangle takes ONE corner's value - every triangle of a
        // smoothly-normalled body then came out a different brightness, the
        // "folded cardboard" facets. Plain chrome is all-white, where the two
        // modes draw the same; the GS pays nothing for the interpolation.
        part.envInfoBag->shadingType = TyraShadingGouraud;
        part.envInfoBag->frustumCulling = PipelineInfoBagFrustumCulling_Precise;
        part.envInfoBag->fullClipChecks = true;
        // Coplanar with the base pass: standard GEQUAL test. (TestOnly's
        // alpha-fail FB_ONLY trick corrupted close-up frames - see below.)
        part.envInfoBag->zTestType = PipelineZTest_Standard;
        // GS fog would ADD the fog color through the additive equation
        // (brightening fogged pixels) - the reflection just stays unfogged.
        part.envInfoBag->fogDisabled = true;
        part.envColorBag = std::make_unique<StaPipColorBag>();
        part.envTexBag = std::make_unique<StaPipTextureBag>();
        part.envBag = std::make_unique<StaPipBag>();
        part.envBag->info = part.envInfoBag.get();
        part.envBag->color = part.envColorBag.get();
        part.envBag->texture = part.envTexBag.get();
        part.envBag->lighting = nullptr;
      }
      // The same matrix the BASE pass draws with, re-pointed on every
      // rebuild: on the matrix path the vertices are LOCAL and VU1 applies
      // objMat - the env bag used to keep the static `model` matrix, which
      // rendered the whole reflection pass in local space around the world
      // origin. Invisible, and measured as EXACTLY invisible: a bodyShine
      // A/B read 0 changed pixels while the pass demonstrably ran.
      part.envInfoBag->model = g.matrixMode ? &g.objMat : &model;
      // Additive equation Cv = Cs*FIX/128 + Cd; FIX 128 = full strength.
      const float fix = envStr * 128.0F + 0.5F;
      part.envInfoBag->additiveBlendFix =
          fix > 255.0F ? 255 : (fix < 1.0F ? 1 : (u8)fix);
      part.envColors.bind(part.envColorBag);
      part.envTexBag->texture = envTex;
      // "-rounded" materials: overwrite the captured face normals with
      // directions radiating from the part centroid - a flat face then
      // sweeps a gradient of the sphere map instead of showing one uniform
      // sample (the viewport shader mirrors this via uReflRounded).
      const bool envRounded = o.data.type == 5
                                  ? gm->parts[billboard ? g.impostorView : pi].reflRounded
                                  : (gmat && gmat->reflRounded);
      if (envRounded && !part.vertices.empty()) {
        const u32 nv = static_cast<u32>(part.vertices.size());
        float cx = 0.0F, cy = 0.0F, cz = 0.0F;
        for (u32 vi = 0; vi < nv; ++vi) {
          cx += part.vertices[vi].x;
          cy += part.vertices[vi].y;
          cz += part.vertices[vi].z;
        }
        cx /= (float)nv, cy /= (float)nv, cz /= (float)nv;
        for (u32 vi = 0; vi < nv; ++vi) {
          float dx = part.vertices[vi].x - cx;
          float dy = part.vertices[vi].y - cy;
          float dz = part.vertices[vi].z - cz;
          const float l = sqrtf(dx * dx + dy * dy + dz * dz);
          if (l > 0.0001F)
            dx /= l, dy /= l, dz /= l;
          else
            dx = 0.0F, dy = 1.0F, dz = 0.0F;
          part.envNormals[vi].set(dx, dy, dz, 0.0F);
        }
      }
      // The normals ride in the ST slot and the TCE programs (cull/as_is/
      // clip) compute the matcap ST from the per-mesh camera basis - zero
      // EE per-vertex work, no pipeline barriers, in both clipping modes.
      part.envNormals.bind(part.envTexBag);
      part.envTexBag->coordinatesAreNormals = true;
      part.vertices.bind(part.envBag);
      part.envBag->count = static_cast<u32>(part.vertices.size());
      part.envBag->bboxVersion = part.bag->bboxVersion;
    } else {
      part.envBag.reset();
    }

    // The scene lightmap passes. ONE atlas texture, read twice - texturing is
    // MODULATE, so the vertex color of each pass picks which of its channels
    // that pass can see:
    //   occlusion: BLACK vertex color -> Cs.rgb = 0 and Cs.a = the atlas
    //     alpha, and the alpha-over blend is then an exact per-pixel multiply
    //     (Cd * (1 - a)). Black matters - a white vertex color would drag the
    //     baked light in RGB into the multiply.
    //   emissive light: WHITE vertex color -> Cs.rgb = the atlas RGB, added
    //     straight onto the frame. fogDisabled for the same reason the
    //     reflection pass sets it: GS fog would ADD the fog color through an
    //     additive equation and brighten fogged pixels.
    // Both reuse this part's vertices/STs/bboxVersion, like the env pass.
    const bool haveLightmap = !part.aoSts.empty() &&
                              part.aoSts.size() == part.vertices.size() &&
                              aoAtlasTexture;
    if (haveLightmap && SCENE_AO_ENABLED && layerInfoBag) {
      part.aoCols.assign(part.vertices.size(), Color(0.0F, 0.0F, 0.0F, 128.0F));
      if (!part.aoBag) {
        part.aoColorBag = std::make_unique<StaPipColorBag>();
        part.aoTexBag = std::make_unique<StaPipTextureBag>();
        part.aoBag = std::make_unique<StaPipBag>();
        part.aoBag->info = layerInfoBag.get();
        part.aoBag->color = part.aoColorBag.get();
        part.aoBag->texture = part.aoTexBag.get();
        part.aoBag->lighting = nullptr;
      }
      part.aoCols.bind(part.aoColorBag);
      part.aoTexBag->texture = aoAtlasTexture;
      part.aoSts.bind(part.aoTexBag);
      part.vertices.bind(part.aoBag);
      part.aoBag->count = static_cast<u32>(part.vertices.size());
      part.aoBag->bboxVersion = part.bag->bboxVersion;
    } else {
      part.aoBag.reset();
    }
    const bool lightmapLit =
        SCENE_AO_ATLAS_LIT && index < SCENE_OBJECT_COUNT &&
        SCENE_AO_ATLAS_LIT[index] != 0;
    if (haveLightmap && lightmapLit && lightAddInfoBag) {
      part.emisCols.assign(part.vertices.size(),
                           Color(128.0F, 128.0F, 128.0F, 128.0F));
      if (!part.emisBag) {
        part.emisColorBag = std::make_unique<StaPipColorBag>();
        part.emisTexBag = std::make_unique<StaPipTextureBag>();
        part.emisBag = std::make_unique<StaPipBag>();
        part.emisBag->info = lightAddInfoBag.get();
        part.emisBag->color = part.emisColorBag.get();
        part.emisBag->texture = part.emisTexBag.get();
        part.emisBag->lighting = nullptr;
      }
      part.emisCols.bind(part.emisColorBag);
      part.emisTexBag->texture = aoAtlasTexture;
      part.aoSts.bind(part.emisTexBag);
      part.vertices.bind(part.emisBag);
      part.emisBag->count = static_cast<u32>(part.vertices.size());
      part.emisBag->bboxVersion = part.bag->bboxVersion;
    } else {
      part.emisBag.reset();
    }
    // Dynamic lighting: swap this part onto the LIT VU1 program. The engine
    // asserts that a lit bag has no per-vertex colors, so the base color
    // becomes ONE value and every bit of shading comes from VU1's N.L against
    // the light bag the frame loop refills (updateDynLitObjects).
    if (dynLit && part.litNormals.size() == part.vertices.size() &&
        !part.vertices.empty()) {
      // The albedo the light colors get folded into - the same product the
      // baked path would have put in the vertex colors.
      const bool litTextured = o.data.type == 5 && gm && pi < (int)gm->parts.size()
                                   ? gm->parts[billboard ? g.impostorView : pi].texture != nullptr
                                   : (gmat && gmat->texture);
      const float* kd = o.data.type == 5 && gm && pi < (int)gm->parts.size()
                            ? gm->parts[billboard ? g.impostorView : pi].kd
                            : (gmat ? gmat->kd : nullptr);
      for (int k = 0; k < 3; ++k)
        part.litAlbedo[k] = o.data.color[k] * (kd ? kd[k] : 1.0F);
      // Same split pushVert makes for the baked path: modulation scale for a
      // textured surface, the full 0..255 for an untextured one.
      part.litScale = litTextured ? 128.0F : 255.0F;
      part.litBase = Color(128.0F, 128.0F, 128.0F, 128.0F);
      if (!part.litBag) {
        part.litColorBag = std::make_unique<StaPipColorBag>();
        part.litBag = std::make_unique<StaPipLightingBag>();
        part.litLights = std::make_unique<PipelineDirLightsBag>(true);
      }
      part.litColorBag->single = &part.litBase;
      part.litColorBag->many = nullptr;
      // Like the static path, a lit bag shades per VERTEX. With
      // flat shading one corner's normal lights the whole triangle - on a
      // cylinder that lights half the segments off a normal pointing away and
      // the object comes out dark and hard-banded (it did).
      part.infoBag->shadingType = TyraShadingGouraud;
      part.litBag->lightMatrix = part.infoBag->model;
      part.litNormals.bind(part.litBag);
      part.litLights->setLightsManually(part.litColors, part.litDirs);
      part.litBag->dirLights = part.litLights.get();
      part.bag->color = part.litColorBag.get();
      part.bag->lighting = part.litBag.get();
      // Seed the colors now: a rebuild triggered from inside renderObjects
      // draws this bag before the next updateDynLitObjects (see
      // fillDynLitColors), and a lit bag handed the zero-initialized array
      // renders the object black.
      needsLitSeed = true;
    } else if (part.litBag) {
      part.infoBag->shadingType = TyraShadingGouraud;
      part.litBag.reset();
      part.litLights.reset();
      part.litColorBag.reset();
      part.bag->color = part.colorBag.get();
      part.bag->lighting = nullptr;
    }

    // Last, once every bag of this part has its final program shape (the
    // dyn-lit swap above changes the base bag's): give the base pass and its
    // coplanar companions ONE package size. LOD tiers only re-aim the
    // pointers, never the program class, so this pin survives applyGeoLod.
    pinPackageSize({part.bag.get(), part.envBag.get(), part.aoBag.get(),
                    part.emisBag.get()},
                   part.stripRun);
  }
  g_litNormals = nullptr;
  // Keep a single conservative AABB across all material parts. It is built
  // alongside geometry (never per frame), then renderScene can reject a fully
  // off-screen model before submitting every part to StaPip. LOD tiers only
  // remove vertices, so the tier-0 box remains conservative for them too.
  // Every object gets one, a single box included: StaPip's own classification
  // of an off-screen bag costs ~17 us on a physical PS2 (bounds, program,
  // transform cache) against ~1 us for this test, and it is paid again for
  // each companion bag - lightmap, emission, env pass. Motor District start
  // pose: 64 of the 77 objects that reached render() drew nothing, 0.43 ms of
  // bounds (docs/profiling.md, "The game side of the object loop").
  g.coarseBoxValid = false;
  if (!g.parts.empty()) {
    Vec4 coarseMin(1e30F, 1e30F, 1e30F, 1.0F);
    Vec4 coarseMax(-1e30F, -1e30F, -1e30F, 1.0F);
    // A shared instance's box: the eight corners of each part's model-space
    // box through objMat, boxed again in WORLD space. Static, so it is built
    // once here and coarseObjectOutside tests it against the world planes
    // like a solo bake's - moving the six planes into every shared object's
    // own space instead cost ~0.6 ms a frame over a streamed city's ~360
    // in-range objects (PCSX2). It bounds the rotated box, so it is never
    // smaller than the geometry; for the usual 0/90/180/270 yaw it is exact.
    for (const GeoPart& part : g.parts)
      if (part.shared && part.bag && !part.shared->vertices.empty()) {
        for (int k = 0; k < 8; ++k) {
          const Vec4 c((k & 1) ? part.shared->mx[0] : part.shared->mn[0],
                       (k & 2) ? part.shared->mx[1] : part.shared->mn[1],
                       (k & 4) ? part.shared->mx[2] : part.shared->mn[2], 1.0F);
          const Vec4 w = g.objMat * c;
          if (w.x < coarseMin.x) coarseMin.x = w.x;
          if (w.y < coarseMin.y) coarseMin.y = w.y;
          if (w.z < coarseMin.z) coarseMin.z = w.z;
          if (w.x > coarseMax.x) coarseMax.x = w.x;
          if (w.y > coarseMax.y) coarseMax.y = w.y;
          if (w.z > coarseMax.z) coarseMax.z = w.z;
        }
        g.coarseBoxValid = true;
      }
    for (const GeoPart& part : g.parts)
      for (const Vec4& v : part.vertices) {
        if (v.x < coarseMin.x) coarseMin.x = v.x;
        if (v.y < coarseMin.y) coarseMin.y = v.y;
        if (v.z < coarseMin.z) coarseMin.z = v.z;
        if (v.x > coarseMax.x) coarseMax.x = v.x;
        if (v.y > coarseMax.y) coarseMax.y = v.y;
        if (v.z > coarseMax.z) coarseMax.z = v.z;
        g.coarseBoxValid = true;
      }
    if (g.coarseBoxValid) {
      Vec4 corners[2] = {coarseMin, coarseMax};
      g.coarseBox = CoreBBox(corners, 2);
    }
  }
  if (needsLitSeed) fillDynLitColors(index);
}



// Draw one cheap silhouette-volume into an environment map. The target is
// 128x128 and sphere-mapped afterwards, so material seams and facade detail
// are usually sub-pixel there; paying one bag and one package for the object's
// bounds is the useful approximation. Main-view geometry is untouched.
void TerrainGame::renderReflectionProxy(int index) {
  ObjectGeometry& g = objectGeometry[index];
  if (!g.reflectionProxy) {
    Vec4 mn(1e30F, 1e30F, 1e30F, 1.0F), mx(-1e30F, -1e30F, -1e30F, 1.0F);
    bool any = false;
    float cr=0, cg=0, cb=0, cn=0;
    // A shared instance keeps its arrays in the model's bake and the colour
    // pool (model space - the space the matrix below expects); everything
    // else in its own tier-0 arrays.
    for (const GeoPart& src : g.parts) {
      const BagArray<Vec4>& sv = src.shared ? src.shared->vertices : src.vertices;
      const BagArray<Color>& sc =
          src.sharedCols ? src.sharedCols->colors : src.colors;
      for (const Vec4& v : sv) {
        mn.x=fminf(mn.x,v.x); mn.y=fminf(mn.y,v.y); mn.z=fminf(mn.z,v.z);
        mx.x=fmaxf(mx.x,v.x); mx.y=fmaxf(mx.y,v.y); mx.z=fmaxf(mx.z,v.z);
        any = true;
      }
      for (const Color& c : sc) { cr+=c.r; cg+=c.g; cb+=c.b; cn+=1.0F; }
    }
    if (!any) return;
    auto p = std::make_unique<GeoPart>();
    const Vec4 v[8] = {
      {mn.x,mn.y,mn.z,1},{mx.x,mn.y,mn.z,1},{mx.x,mx.y,mn.z,1},{mn.x,mx.y,mn.z,1},
      {mn.x,mn.y,mx.z,1},{mx.x,mn.y,mx.z,1},{mx.x,mx.y,mx.z,1},{mn.x,mx.y,mx.z,1}};
    static const u8 tri[36] = {0,2,1,0,3,2, 4,5,6,4,6,7,
      0,1,5,0,5,4, 3,7,6,3,6,2, 0,4,7,0,7,3, 1,2,6,1,6,5};
    const Color col(cn ? cr/cn : 160.0F, cn ? cg/cn : 160.0F,
                    cn ? cb/cn : 160.0F, 128.0F);
    for (u8 i : tri) { p->vertices.push_back(v[i]); p->colors.push_back(col); }
    p->infoBag = std::make_unique<StaPipInfoBag>();
    p->infoBag->model = (g.matrixMode || g.shared) ? &g.objMat : &model;
    p->infoBag->shadingType = TyraShadingGouraud;
    p->infoBag->frustumCulling = PipelineInfoBagFrustumCulling_Precise;
    p->infoBag->fullClipChecks = true;
    p->colorBag = std::make_unique<StaPipColorBag>();
    p->bag = std::make_unique<StaPipBag>();
    p->bag->info = p->infoBag.get(); p->bag->color = p->colorBag.get();
    p->bag->texture = nullptr; p->bag->lighting = nullptr;
    p->colors.bind(p->colorBag); p->vertices.bind(p->bag);
    p->bag->count = (u32)p->vertices.size();
    p->bag->bboxVersion = ++g_bboxStamp;
    g.reflectionProxy = std::move(p);
  }
  if (g.reflectionProxy->bag) stapip.core.render(g.reflectionProxy->bag.get());
}



bool TerrainGame::coarseObjectOutside(int index) const {
  if (index < 0 || index >= (int)objectGeometry.size()) return false;
  const ObjectGeometry& g = objectGeometry[index];
  // An impostor billboard rewrites its six vertices every frame to face the
  // camera, so a box baked at rebuild time does not bound it.
  if (!g.coarseBoxValid || g.impostor || vuscript::movesGeometry())
    return false;
  Plane localPlanes[6];
  const Plane* planes =
      engine->renderer.core.renderer3D.frustumPlanes.getAll();
  if (g.matrixMode) {  // a shared instance's box is already world space
    CoreBBox::computeObjectSpacePlanes(localPlanes, planes, g.objMat);
    planes = localPlanes;
  }
  return g.coarseBox.frustumCheckAABB(planes) ==
         CoreBBoxFrustum::OUTSIDE_FRUSTUM;
}



// Static mesh LOD (docs/model-pipeline.md). Two object kinds keep the full
// mesh no matter how far away they are, because something else depends on the
// exact tier-0 buffers:
//  - physics fast-path bodies (matrixMode) bake LOCAL-space vertices with the
//    shading frozen at the wake pose; they are also next to the player;
//  - objects with a texture feed, whose colors are flattened and whose STs are
//    V-flipped after the bake - state a tier bake would not reproduce.
// Everything else is fair game: the collider and the AABB are model-level, so
// collision, physics extents and the split-band cull never see a tier.
bool TerrainGame::modelLodEligible(int index) const {
  // A matrix-path body tiers too: its tiers are baked LOCAL (applyGeoLod
  // stages g_bakeLocal from matrixMode), so they stay valid under motion -
  // which is what a vehicle's far tier needs (docs/vehicles.md). A rebuild
  // drops every tier, so a mode change cannot leave a wrong-space one.
  if (objectGeometry[index].impostor) return false;
  for (int fi = 0; fi < OBJECT_FEED_COUNT; ++fi)
    if (OBJECT_FEEDS[fi].scene == currentScene &&
        OBJECT_FEEDS[fi].object == index)
      return false;
  return true;
}



void TerrainGame::applyGeoLod(int index, int pi, int lod) {
  ObjectGeometry& g = objectGeometry[index];
  if (pi >= (int)g.parts.size()) return;
  GeoPart& part = g.parts[pi];
  if (!part.bag) return;
  const RuntimeObject& o = runtimeObjects[index];
  if (o.data.model < 0 || o.data.model >= (int)gameModels.size()) return;
  const GameModel& gmdl = gameModels[o.data.model];
  if (pi >= (int)gmdl.parts.size()) return;
  const GameModelPart& src = gmdl.parts[pi];
  // Clamp per part: a small part may carry fewer tiers than a big one (the
  // bake skips meshes too small to shrink), and it then just stays detailed.
  if (lod > (int)src.lodVerts.size()) lod = (int)src.lodVerts.size();
  if (lod == part.shownLod) return;

  // A shared instance: the tier's positions/STs are the model's (built once
  // for every instance), only its colours are this object's - lit by the same
  // shadeVertexColor as tier 0, pooled the same way.
  if (part.shared && part.sharedCols) {
    SharedGeo& sg = *part.shared;
    if (lod == 0) {
      part.sharedCols->colors.bind(part.colorBag);
      sg.vertices.bind(part.bag);
      part.bag->count = static_cast<u32>(sg.vertices.size());
      part.bag->bboxVersion = sg.stamp;
      part.bag->stripped = part.stripRun != 0;
      if (part.texBag) sg.sts.bind(part.texBag);
    } else {
      // sized once, here, and never again: other instances' bags hold the
      // tiers' content-stamp addresses, which a resize would move
      if (sg.tiers.empty()) sg.tiers.resize(src.lodVerts.size());
      if (lod - 1 >= (int)sg.tiers.size()) return;
      SharedGeo::Tier& st = sg.tiers[lod - 1];
      const bool tierStrip = lod - 1 < (int)src.lodStripVerts.size() &&
                             !src.lodStripVerts[lod - 1].empty() &&
                             part.stripRun != 0;
      const std::vector<float>& sv =
          tierStrip ? src.lodStripVerts[lod - 1] : src.lodVerts[lod - 1];
      if (!st.built) {
        st.built = true;
        st.vertices.reserve(sv.size() / 8);
        st.sts.reserve(sv.size() / 8);
        for (size_t k = 0; k + 7 < sv.size(); k += 8) {
          const float* v = &sv[k];
          st.vertices.push_back(Vec4(v[0], v[1], v[2], 1.0F));
          st.sts.push_back(Vec4(v[6], v[7], 1.0F, 0.0F));
        }
        st.strip = tierStrip;
        st.stamp = ++g_bboxStamp;
      }
      if (st.vertices.empty()) return;  // nothing to show - keep tier 0
      if ((int)part.lods.size() < lod) part.lods.resize(lod);
      GeoPart::Lod& tier = part.lods[lod - 1];
      if (!tier.sharedCols) {
        static BagArray<Color> tierCols;
        tierCols.clear();
        tierCols.reserve(sv.size() / 8);
        stageModelShading(index);
        const SceneObjectData& d = o.data;
        const bool textured = src.texture != nullptr;
        for (size_t k = 0; k + 7 < sv.size(); k += 8) {
          const float* v = &sv[k];
          V3 p = {v[0], v[1], v[2]};
          p.x *= d.scale[0], p.y *= d.scale[1], p.z *= d.scale[2];
          p = rotated(p, d.rotation);
          const V3 n = rotated(V3{v[3], v[4], v[5]}, d.rotation);
          const V3 wp = {p.x + d.position[0], p.y + d.position[1],
                         p.z + d.position[2]};
          tierCols.push_back(shadeVertexColor(d, wp, n, v[6], v[7], src.kd,
                                              src.ke, textured, 255));
        }
        resetModelShading();
        tier.sharedCols = poolColors(tierCols);
      }
      tier.sharedCols->colors.bind(part.colorBag);
      st.vertices.bind(part.bag);
      part.bag->count = static_cast<u32>(st.vertices.size());
      part.bag->bboxVersion = st.stamp;
      part.bag->stripped = st.strip;
      if (part.texBag) st.sts.bind(part.texBag);
    }
    part.shownLod = lod;
    g.apronVerts.clear();
    g.hullProxyVerts.clear();
    return;
  }

  if (lod == 0) {
    part.colors.bind(part.colorBag);
    part.vertices.bind(part.bag);
    part.bag->count = static_cast<u32>(part.vertices.size());
    part.bag->bboxVersion = part.baseStamp;
    // Tier 0 is the only one the bake strips (docs/model-pipeline.md), so the
    // topology flag moves with the pointer. packageSize stays pinned either
    // way: the run length is legal for a list too, just slightly smaller.
    part.bag->stripped = part.stripRun != 0;
    if (part.texBag) part.sts.bind(part.texBag);
    if (part.envBag) {
      part.envColors.bind(part.envColorBag);
      part.envNormals.bind(part.envTexBag);
      part.vertices.bind(part.envBag);
      part.envBag->count = part.bag->count;
      part.envBag->bboxVersion = part.baseStamp;
      part.envBag->stripped = part.bag->stripped;
    }
  } else {
    if ((int)part.lods.size() < lod) part.lods.resize(lod);
    GeoPart::Lod& tier = part.lods[lod - 1];
    // A tier's topology: the list, unless the bake left a strip twin (an
    // authored vehicle far tier). The flag used to stay at tier 0's value,
    // so a stripped body drew its tier LIST as a strip - spikes across the
    // car the moment it swapped.
    const bool tierStrip = lod - 1 < (int)src.lodStripVerts.size() &&
                           !src.lodStripVerts[lod - 1].empty() &&
                           part.stripRun != 0;
    if (tier.vertices.empty()) {
      // First time this far away: shade the decimated vertex list exactly the
      // way rebuildObjectGeometry shaded tier 0 (same pushVert, same staging).
      const std::vector<float>& sv =
          tierStrip ? src.lodStripVerts[lod - 1] : src.lodVerts[lod - 1];
      // The staging tier 0 was baked under: imported models get no
      // receive/self AO, DO get global illumination from the probe grid (the
      // whole reason models were left parked on the vertex path), and their
      // own analytic-light lists and pre-lit flag - not the last rebuilt
      // object's, which is what this tier used to inherit.
      stageModelShading(index);
      // A matrix-path object bakes LOCAL tiers, exactly as its tier 0 was
      // baked at promotion; objMat applies the motion to every tier alike.
      g_bakeLocal = g.matrixMode;
      g_envNormals = part.envBag ? &tier.envNormals : nullptr;
      const bool textured = src.texture != nullptr;
      for (size_t k = 0; k + 7 < sv.size(); k += 8) {
        const float* v = &sv[k];
        pushVert(tier.vertices, tier.colors, tier.sts, o.data,
                 {v[0], v[1], v[2]}, {v[3], v[4], v[5]}, v[6], v[7], src.kd,
                 textured, 255, src.ke);
      }
      // ...and hand every global back: g_bakeLocal used to stay set after a
      // matrix-path tier, for whatever baked next (a static batch).
      resetModelShading();
      if (tier.vertices.empty()) return;  // nothing to show - keep tier 0
      if (part.envBag) {
        tier.envColors.assign(tier.vertices.size(),
                              Color(128.0F, 128.0F, 128.0F, 128.0F));
        if (src.reflRounded) {
          // "-rounded": env normals radiate from THIS tier's centroid
          const u32 nv = static_cast<u32>(tier.vertices.size());
          float cx = 0.0F, cy = 0.0F, cz = 0.0F;
          for (u32 vi = 0; vi < nv; ++vi) {
            cx += tier.vertices[vi].x;
            cy += tier.vertices[vi].y;
            cz += tier.vertices[vi].z;
          }
          cx /= (float)nv, cy /= (float)nv, cz /= (float)nv;
          for (u32 vi = 0; vi < nv; ++vi) {
            float dx = tier.vertices[vi].x - cx;
            float dy = tier.vertices[vi].y - cy;
            float dz = tier.vertices[vi].z - cz;
            const float l = sqrtf(dx * dx + dy * dy + dz * dz);
            if (l > 0.0001F)
              dx /= l, dy /= l, dz /= l;
            else
              dx = 0.0F, dy = 1.0F, dz = 0.0F;
            tier.envNormals[vi].set(dx, dy, dz, 0.0F);
          }
        }
      }
      tier.stamp = ++g_bboxStamp;
    }
    tier.colors.bind(part.colorBag);
    tier.vertices.bind(part.bag);
    part.bag->count = static_cast<u32>(tier.vertices.size());
    part.bag->bboxVersion = tier.stamp;
    part.bag->stripped = tierStrip;
    if (part.texBag) tier.sts.bind(part.texBag);
    if (part.envBag) {
      tier.envColors.bind(part.envColorBag);
      tier.envNormals.bind(part.envTexBag);
      tier.vertices.bind(part.envBag);
      part.envBag->count = part.bag->count;
      part.envBag->bboxVersion = tier.stamp;
      part.envBag->stripped = tierStrip;
    }
  }
  part.shownLod = lod;
  // The textured-AO pass points at tier 0's vertices and its own ST array;
  // models never get atlas regions, so it can only exist on primitives - but
  // stay safe and drop it rather than draw a mismatched count.
  if (part.aoBag && lod != 0) part.aoBag.reset();
  // The highlight shells were built from the other tier's vertices.
  g.apronVerts.clear();
  g.hullProxyVerts.clear();
}

            // player shove gain (scaled 1/mass)

// World-space AABB half-extents + center offset from data.position of a solid
// object - models use their mesh AABB, exactly like collidePlayer.
void TerrainGame::physExtents(const SceneObjectData& d, const GameModel* gm,
                              const SkelModel* anim, float* cOff, float* ext) {
  cOff[0] = cOff[1] = cOff[2] = 0.0F;
  for (int a = 0; a < 3; ++a) ext[a] = 0.5F * d.scale[a];
  const float* mn = gm ? gm->mn : (anim ? anim->min : nullptr);
  const float* mx = gm ? gm->mx : (anim ? anim->max : nullptr);
  if (mn && mx) {
    for (int a = 0; a < 3; ++a) {
      cOff[a] = 0.5F * (mn[a] + mx[a]) * d.scale[a];
      ext[a] = 0.5F * (mx[a] - mn[a]) * d.scale[a];
      if (ext[a] < 0.01F) ext[a] = 0.01F;
    }
  }
}



// A moving body renders through objMat (local vertices, VU1 applies the
// motion) unless a consumer of its vertex arrays assumes world space: the
// usable-highlight hull/apron and reflective matcap normals both do, and
// animated models already ride their own animMat.
bool TerrainGame::physFastPathEligible(int index) const {
  const RuntimeObject& o = runtimeObjects[index];
  const int t = o.data.type;
  if (t != 0 && t != 1 && t != 2 && t != 3 && t != 5 && t != 12) return false;
  if (o.data.usable) return false;
  if (t == 5) {
    if (o.data.animModel >= 0) return false;
    if (o.data.model < 0 || o.data.model >= (int)gameModels.size())
      return false;
  }
  // Reflective parts used to be excluded here, because their env normals
  // were baked in WORLD space and froze the reflection at the promotion
  // pose. The local bake captures LOCAL normals now and renderEnvPass folds
  // the object's rotation into the env camera basis (dot(R n, e) =
  // dot(n, R^T e)), so a mover with a refl part - a shiny car above all -
  // keeps both the matrix path and a correct reflection.
  return true;
}



// Rotation columns come from the same rotated() the vertex bake uses, so the
// matrix path and the bake path can never disagree on the Euler order. Scale
// is baked into the local vertices - the basis stays unit-length.
void TerrainGame::updateObjMat(int index) {
  const RuntimeObject& o = runtimeObjects[index];
  M4x4& m = objectGeometry[index].objMat;
  const V3 bx = rotated({1.0F, 0.0F, 0.0F}, o.data.rotation);
  const V3 by = rotated({0.0F, 1.0F, 0.0F}, o.data.rotation);
  const V3 bz = rotated({0.0F, 0.0F, 1.0F}, o.data.rotation);
  m.identity();
  m.data[0] = bx.x, m.data[1] = bx.y, m.data[2] = bx.z;
  m.data[4] = by.x, m.data[5] = by.y, m.data[6] = by.z;
  m.data[8] = bz.x, m.data[9] = bz.y, m.data[10] = bz.z;
  m.data[12] = o.data.position[0];
  m.data[13] = o.data.position[1];
  m.data[14] = o.data.position[2];
  // A shared instance draws the model's UNSCALED bake, so the scale lives in
  // the matrix: columns times scale = T * R * S, the order pushVert applies
  // them in (scale, rotate, translate).
  if (objectGeometry[index].shared) {
    for (int k = 0; k < 3; ++k) {
      m.data[k] *= o.data.scale[0];
      m.data[4 + k] *= o.data.scale[1];
      m.data[8 + k] *= o.data.scale[2];
    }
  }
}



// Solid enough to block/bump a physics body (matches collidePlayer's list).
bool TerrainGame::physObstacle(const SceneObjectData& d) {
  if (d.collision == 2) return false;
  const int t = d.type;
  return t != 4 && t != 6 && t != 7 && t != 8 && t != 9 && t != 11 &&
         t != 13 && t != 14 && t != 17 && t != 20;
}



// ---------------------------------------------------------------------------
// Static batching (STATIC_BATCHING): every StaPip submit costs ~0.7-1.5 ms
// of fixed EE overhead on real hardware regardless of vertex count, so a
// scene of many small objects pays for its object COUNT, not its geometry
// (twice over in split screen). Eligible primitives and compact imported-model
// parts merge into combined world-space bags instead, grouped by texture in a
// coarse world cell. Large models remain solo: widening a batch around whole
// districts would defeat the engine's whole-bag frustum cut, the same reason
// terrain is chunked.
void TerrainGame::buildStaticBatchList() {
  staticBatches.clear();
  objectBatchOf.assign(SCENE_OBJECT_COUNT, -1);
  if (!STATIC_BATCHING) return;
  if (!batchInfoBag) {
    batchInfoBag = std::make_unique<StaPipInfoBag>();
    batchInfoBag->model = &model;
    batchInfoBag->shadingType = TyraShadingGouraud;
    // Same rules as the per-object bags: always classify against the
    // frustum (raw submission wraps the GS raster window) with full clip
    // checks.
    batchInfoBag->frustumCulling = PipelineInfoBagFrustumCulling_Precise;
    batchInfoBag->fullClipChecks = true;
  }
  // Cell width: a quarter of the map on big maps (a 2048-unit map gets a
  // 4x4 grid), but never below 48 units - on a small map a finer grid (or
  // one straddling the origin) splits a handful of objects into
  // single-member batches and the merge wins nothing. The grid anchors at
  // the map corner (terrain is centered on the origin) for the same reason.
  const float mapW =
      TERRAIN_WIDTH > TERRAIN_DEPTH ? TERRAIN_WIDTH : TERRAIN_DEPTH;
  const float baseCellW = mapW * 0.25F > 48.0F ? mapW * 0.25F : 48.0F;
  // ...AND NEVER WIDER THAN THE DRAW DISTANCE ITS MEMBERS SHARE. A quarter of
  // the map is a fraction of the wrong thing: it grows with the MAP, so the
  // bigger the world the coarser the cull, which is backwards. On a 2048-unit
  // map that is a 512-unit cell, and the batch built in it is one bag whose
  // member-centre box renderStaticBatches tests ONCE - so a batch of props
  // that individually vanish at 60 units stays drawn while the camera is
  // within 60 units of a 512-unit box. Measured on examples/large-terrain:
  // +2,015 triangles and +12 packet flushes against the same scene unbatched,
  // which is the widened-bounds regression #269 warned about arriving through
  // the draw-distance test rather than through the frustum.
  //
  // drawDistance is ALREADY a group key (every member of a batch shares one
  // cut-off), so it is a per-group length the scene states about itself, and
  // capping the cell with it makes the grid as coarse as the content allows
  // instead of as coarse as the map is big. The Motor District is unchanged by
  // construction - its batchable objects carry 145 or 0, and min(80, 145) is
  // still 80 - while large-terrain's 1,100 cones drop from 512 to 60.
  //
  // 0 means unlimited and has no such length, so those groups keep the base
  // cell. That is the remaining hole and it is deliberate: an OCCUPANCY test
  // ("batch only when the members fill their union") was tried on paper and
  // rejected, because it measures the wrong thing for this engine. The
  // district's win comes precisely from merging small props that are sparse in
  // their cell - three boxes of span 12 in an 80-unit cell fill 6.7% of it -
  // so any ratio strict enough to catch a 512-unit cell also throws away the
  // batches that pay. What costs is EXTENT AGAINST THE CULL DISTANCE, which is
  // what the cap above bounds and what a fill ratio cannot see.
  auto cellFor = [&](float drawDistance) -> float {
    if (drawDistance <= 0.0F) return baseCellW;
    return drawDistance < baseCellW ? drawDistance : baseCellW;
  };
  std::vector<int> keyX, keyZ, keyL;  // cell + lamp, only needed while grouping
  // WHICH DYNAMIC LAMP REACHES THIS OBJECT, or -1. This is a grouping key, not
  // a render decision, and it exists because of how the engine lights a bag:
  // StaPipCore::render gives each bag ONE light slot, picked from that bag's
  // world bounding sphere. Merge a lamp-lit prop with an unlit one and the
  // merged sphere picks a single lamp for both - so the lit one can lose its
  // highlight, or the unlit one gain one it should not have. On the Motor
  // District at night that would have hit 7 of 49 batches (a streetlight
  // standing under its own lamp merged with one standing under nothing,
  // because they share a texture and a cell).
  //
  // Centre-vs-radius, not the engine's brightness x level x falloff score: the
  // key only has to keep "a lamp reaches this" apart from "nothing reaches
  // this", and every member of a lamp's group is within that lamp's radius, so
  // the merged sphere stays in its neighbourhood. A lamp switched off (or the
  // whole set, in daylight) makes every bag pick nothing, and members agree
  // for that reason instead.
  auto lampOf = [&](const SceneObjectData& d) -> int {
    int best = -1;
    float bestD2 = 0.0F;
    for (size_t li = 0; li < g_dynLights.size(); ++li) {
      const SceneObjectData& L = SCENE_OBJECTS[g_dynLights[li].objIndex];
      if (L.lightRadius <= 0.0F) continue;
      const float dx = L.position[0] - d.position[0];
      const float dy = L.position[1] - d.position[1];
      const float dz = L.position[2] - d.position[2];
      const float d2 = dx * dx + dy * dy + dz * dz;
      if (d2 > L.lightRadius * L.lightRadius) continue;  // no influence at all
      if (best < 0 || d2 < bestD2) {
        best = (int)li;
        bestD2 = d2;
      }
    }
    return best;
  };
  // Draw distance joins the key. A batch is ONE bag with one cut-off test, so
  // members that disagree about the distance must not share one - otherwise
  // the nearest member's number would silently extend every other member's.
  // Objects that leave it at 0 group exactly as they did before.
  auto addMember = [&](int object, int part, Texture* texture, int cx, int cz,
                       float dd, int lamp, unsigned int stripRun) {
    int bi = -1;
    for (int b = 0; b < (int)staticBatches.size(); ++b)
      if (staticBatches[b].texture == texture && keyX[b] == cx &&
          keyZ[b] == cz && staticBatches[b].drawDistance == dd &&
          keyL[b] == lamp && staticBatches[b].stripRun == stripRun) {
        bi = b;
        break;
      }
    if (bi < 0) {
      staticBatches.emplace_back();
      staticBatches.back().texture = texture;
      staticBatches.back().drawDistance = dd;
      staticBatches.back().stripRun = stripRun;
      keyX.push_back(cx);
      keyZ.push_back(cz);
      keyL.push_back(lamp);
      bi = (int)staticBatches.size() - 1;
    }
    staticBatches[bi].members.push_back({object, part});
  };
  for (int i = 0; i < SCENE_OBJECT_COUNT; ++i) {
    const SceneObjectData& d = SCENE_OBJECTS[i];
    if (!d.batchStatic) continue;
    // Vehicles, endless scrollers and any future owner of the matrix fast
    // path move after scene load. Baking one into world-space static geometry
    // makes the solo renderer skip it forever; a multi-part model whose parts
    // share a texture could even form a "batch" with itself. setupVehicles()
    // and other runtime owners set this request before this list is built.
    if (runtimeObjects[i].wantsMatrixPath) continue;
    // Materials of always-resident objects are loaded by now; a reflective
    // one draws a second additive env pass per bag - keep those objects on
    // the solo path, which already handles the env bag.
    // One grid per draw-distance class, never coarser than that class's own
    // cut-off. drawDistance is part of the group key, so members that land in
    // one batch always agreed about this width - the classes have different
    // grids and cannot merge across them.
    const float cellW = cellFor(d.drawDistance);
    const int cx = (int)floorf((d.position[0] + 0.5F * mapW) / cellW);
    const int cz = (int)floorf((d.position[2] + 0.5F * mapW) / cellW);
    const int lamp = lampOf(d);
    if (d.type == 5) {
      if (d.model < 0 || d.model >= (int)gameModels.size()) continue;
      const GameModel& gm = gameModels[d.model];
      // Position-cell grouping is only a useful spatial bound for props that
      // are small relative to that cell. Large architecture keeps its own
      // object/part boxes; earlier material-only grouping widened those bags
      // enough to cost more than the removed submits.
      const float spanX = (gm.mx[0] - gm.mn[0]) * fabsf(d.scale[0]);
      const float spanZ = (gm.mx[2] - gm.mn[2]) * fabsf(d.scale[2]);
      if (sqrtf(spanX * spanX + spanZ * spanZ) > 0.5F * cellW) continue;
      bool reflective = false;
      for (const GameModelPart& p : gm.parts)
        if (p.reflTexture) { reflective = true; break; }
      if (reflective || gm.parts.empty()) continue;
      for (int pi = 0; pi < (int)gm.parts.size(); ++pi)
        addMember(i, pi, gm.parts[pi].texture, cx, cz, d.drawDistance, lamp,
                  gm.parts[pi].stripRun);
    } else {
      if (d.material >= 0 &&
          (d.material >= (int)gameMaterials.size() ||
           gameMaterials[d.material].reflTexture))
        continue;
      Texture* texture =
          d.material >= 0 ? gameMaterials[d.material].texture : nullptr;
      addMember(i, -1, texture, cx, cz, d.drawDistance, lamp, 0u);
    }
  }
  // A model is skipped by the solo path as ONE object, so batching it is also
  // all-or-nothing. Material parts group independently and some of their groups
  // can be singletons; keeping only the groups that survived would draw a roof
  // or windows from a batch, skip the whole solo model, and leave its walls
  // missing. Prune incomplete objects, then repeat because that removal can
  // turn another object's group into a singleton. The fixed point contains
  // only objects whose every part has exactly one surviving batch member.
  int partialFallback = 0;
  for (;;) {
    for (size_t b = 0; b < staticBatches.size();) {
      if (staticBatches[b].members.size() < 2)
        staticBatches.erase(staticBatches.begin() + (long)b);
      else
        ++b;
    }
    std::vector<unsigned short> memberCount(SCENE_OBJECT_COUNT, 0);
    for (const StaticBatch& b : staticBatches)
      for (const StaticBatchMember& m : b.members)
        if (m.object >= 0 && m.object < SCENE_OBJECT_COUNT)
          ++memberCount[m.object];
    std::vector<unsigned char> incomplete(SCENE_OBJECT_COUNT, 0);
    bool anyIncomplete = false;
    for (int i = 0; i < SCENE_OBJECT_COUNT; ++i) {
      if (memberCount[i] == 0) continue;
      const SceneObjectData& d = SCENE_OBJECTS[i];
      unsigned int expected = 1;
      if (d.type == 5) {
        if (d.model < 0 || d.model >= (int)gameModels.size()) expected = 0;
        else expected = (unsigned int)gameModels[d.model].parts.size();
      }
      if (memberCount[i] == expected) continue;
      incomplete[i] = 1;
      anyIncomplete = true;
      ++partialFallback;
    }
    if (!anyIncomplete) break;
    for (StaticBatch& b : staticBatches)
      for (size_t k = 0; k < b.members.size();) {
        const int object = b.members[k].object;
        if (object >= 0 && object < SCENE_OBJECT_COUNT && incomplete[object])
          b.members.erase(b.members.begin() + (long)k);
        else
          ++k;
      }
  }
  objectBatchOf.assign(SCENE_OBJECT_COUNT, -1);
  for (int bi = 0; bi < (int)staticBatches.size(); ++bi)
    for (const StaticBatchMember& m : staticBatches[bi].members) {
      // -2 means that a multi-part model belongs to more than one batch.
      // Yes/no callers test != -1; a helper that needs one concrete batch
      // deliberately accepts only a non-negative index.
      if (objectBatchOf[m.object] == -1)
        objectBatchOf[m.object] = (short)bi;
      else if (objectBatchOf[m.object] != bi)
        objectBatchOf[m.object] = -2;
    }
  int batched = 0;
  for (int i = 0; i < SCENE_OBJECT_COUNT; ++i) {
    if (objectBatchOf[i] == -1) continue;
    ++batched;
    // The scene-load dirty flag is consumed only by real membership: the
    // batch itself starts dirty and bakes on the first renderScene. A later
    // dirty flag therefore means a runtime mutation and triggers demotion.
    runtimeObjects[i].dirty = false;
  }
  // The batched/solo split and the widest cell any batch was allowed, so an
  // A/B can read the grouping decision out of the game's own log instead of
  // inferring it from triangle counts - and so two arms of a cell change say
  // which is which. `eligible` counts the batchStatic-flagged objects, so
  // eligible - batched is the number that stayed solo (a singleton group, a
  // large model, or a reflective one).
  int eligible = 0;
  for (int i = 0; i < SCENE_OBJECT_COUNT; ++i)
    if (SCENE_OBJECTS[i].batchStatic) ++eligible;
  float widestCell = 0.0F;
  for (int i = 0; i < SCENE_OBJECT_COUNT; ++i)
    if (SCENE_OBJECTS[i].batchStatic) {
      const float c = cellFor(SCENE_OBJECTS[i].drawDistance);
      if (c > widestCell) widestCell = c;
    }
  TYRA_LOG("Static batching: ", batched, " objects in ",
           (int)staticBatches.size(), " batches");
  TYRA_LOG("Static batching: eligible ", eligible, ", solo ",
           eligible - batched, ", base cell ", (int)baseCellW, ", widest cell ",
           (int)widestCell);
  TYRA_LOG("Static batching: partial models kept solo ", partialFallback);
  if (TEXTURE_ATLAS_INFO[0]) TYRA_LOG(TEXTURE_ATLAS_INFO);
}



// One batch's bake: re-run the primitive builders or imported-model part bake
// for every shown member into the combined arrays - world-space vertices with
// baked lighting, byte-identical to the solo path for that object. The
// heap arrays are reused across rebuilds; the engine's frustum-bbox cache
// is keyed by (pointer, version), so the bboxVersion bump below is what
// keeps reused pointers from resurrecting stale boxes.
void TerrainGame::rebuildStaticBatch(StaticBatch& b) {
  b.dirty = false;
  b.vertices.clear();
  b.colors.clear();
  b.sts.clear();
  b.shown.assign(b.members.size(), 0);
  // A batched member never carries a lightmap region (the atlas keeps its
  // receivers solo), so its global illumination comes from the probe grid.
  // Staged explicitly: these are globals, and inheriting whatever the last
  // rebuildObjectGeometry left set would shade a whole batch by accident.
  g_giLightmap = false;
  g_giProbeShade = SCENE_PROBES != nullptr;
  // Strip or list for the WHOLE batch, decided before a single vertex is
  // emitted. It has to be all-or-nothing: the combined array carries one
  // topology, so emitting one member's strip beside another's list would hand
  // the strip's vertices to a triangle-list walk and draw shredded geometry.
  // stripRun is part of the group key, so this normally just confirms what
  // grouping already decided; the loop below is the guard for a part whose
  // baked strip is missing or not a whole number of runs.
  bool useStrips = b.stripRun != 0;
  if (useStrips)
    for (const StaticBatchMember& m : b.members) {
      const RuntimeObject& mo = runtimeObjects[m.object];
      if (m.part < 0 || mo.data.model < 0 ||
          mo.data.model >= (int)gameModels.size() ||
          m.part >= (int)gameModels[mo.data.model].parts.size()) {
        useStrips = false;
        break;
      }
      const GameModelPart& p = gameModels[mo.data.model].parts[m.part];
      if (p.stripRun != b.stripRun || p.stripVerts.empty()) {
        useStrips = false;
        break;
      }
    }
  // The member-centre box the draw-distance test reads. Built over EVERY
  // member, shown or not: a hidden member needs no drawing, but letting
  // visibility move the box would make the batch's cut-off flicker with
  // hide/show events for no benefit. Demotion DOES change it, and demotion
  // always goes through this function (renderStaticBatches sets stale).
  for (size_t k = 0; k < b.members.size(); ++k) {
    const float* p = runtimeObjects[b.members[k].object].data.position;
    for (int a = 0; a < 3; ++a) {
      if (k == 0 || p[a] < b.ddMin[a]) b.ddMin[a] = p[a];
      if (k == 0 || p[a] > b.ddMax[a]) b.ddMax[a] = p[a];
    }
  }
  for (size_t k = 0; k < b.members.size(); ++k) {
    const StaticBatchMember member = b.members[k];
    RuntimeObject& o = runtimeObjects[member.object];
    g_aoOff = false;
    g_prelitTex = false;
    g_giProbeShade = SCENE_PROBES != nullptr;
    // Members are never dirty here: scene load consumes the flag at
    // grouping time and renderStaticBatches demotes dirtied members before
    // calling this.
    const bool show = o.active && o.visible;
    b.shown[k] = show ? 1 : 0;
    if (!show) continue;
    // Per-MEMBER analytic-light pruning: pushVert reads the g_*Local lists,
    // which are per object, so a batch that collected them once would shade
    // every member with the first member's neighbours. Use the same primitive
    // or imported-model bounding sphere as rebuildObjectGeometry.
    {
      const int mi = member.object;
      const float sx = o.data.scale[0], sy = o.data.scale[1], sz = o.data.scale[2];
      float rad = 0.87F * sqrtf(sx * sx + sy * sy + sz * sz);
      if (member.part >= 0 && o.data.model >= 0 &&
          o.data.model < (int)gameModels.size()) {
        const GameModel& gm = gameModels[o.data.model];
        const float ex = fmaxf(fabsf(gm.mn[0]), fabsf(gm.mx[0])) * fabsf(sx);
        const float ey = fmaxf(fabsf(gm.mn[1]), fabsf(gm.mx[1])) * fabsf(sy);
        const float ez = fmaxf(fabsf(gm.mn[2]), fabsf(gm.mx[2])) * fabsf(sz);
        rad = sqrtf(ex * ex + ey * ey + ez * ez);
      }
      const int self = mi < SCENE_OBJECT_COUNT ? mi : -1;
      aoCollectLocal(o.data.position[0], o.data.position[1], o.data.position[2],
                     rad, self);
      emisCollectLocal(o.data.position[0], o.data.position[1],
                       o.data.position[2], rad, self);
    }
    if (member.part >= 0 && o.data.model >= 0 &&
        o.data.model < (int)gameModels.size() &&
        member.part < (int)gameModels[o.data.model].parts.size()) {
      const GameModelPart& src = gameModels[o.data.model].parts[member.part];
      const bool textured = src.texture != nullptr;
      // Take the STRIP twin when this is a strip batch. Re-emitting the list
      // here is what used to make batching cost more than it saved on a
      // district of stripped models: the merged bag threw away the vertex
      // saving the bake had already won. `useStrips` was decided for the whole
      // batch above, so members can never disagree about topology.
      const std::vector<float>& sv = useStrips ? src.stripVerts : src.verts;
      const std::vector<unsigned char>& sao =
          useStrips ? src.stripVertexAo : src.vertexAo;
      const bool hasAo = sao.size() * 8 == sv.size();
      g_aoOff = true;
      g_prelitTex = o.data.prelit != 0;
      g_giProbeShade = !g_prelitTex && SCENE_PROBES != nullptr;
      for (size_t vi = 0; vi + 7 < sv.size(); vi += 8) {
        const float* v = &sv[vi];
        pushVert(b.vertices, b.colors, b.sts, o.data, {v[0], v[1], v[2]},
                 {v[3], v[4], v[5]}, v[6], v[7], src.kd, textured,
                 hasAo ? sao[vi / 8] : (unsigned char)255, src.ke);
      }
      // PAD THIS MEMBER UP TO A WHOLE RUN. A baked strip is chopped into runs
      // of AT MOST stripRun vertices and only the runs before the last are
      // padded out (the last one need only be a multiple of 3, meshstrip.hpp),
      // which is fine for a solo bag - it is the end of the array - and wrong
      // the moment another member follows it. Without this the next member
      // would start mid-package and one package would splice two objects into
      // a triangle. Repeating the last vertex is the same trick the baker
      // uses: it makes degenerate triangles the GS rasterises to nothing.
      if (useStrips && !b.vertices.empty())
        while (b.vertices.size() % b.stripRun != 0) {
          b.vertices.push_back(b.vertices.back());
          b.colors.push_back(b.colors.back());
          if (!b.sts.empty()) b.sts.push_back(b.sts.back());
        }
      g_aoOff = false;
      g_prelitTex = false;
    } else {
      const GameMaterial* gmat =
          (o.data.material >= 0 &&
           o.data.material < (int)gameMaterials.size())
              ? &gameMaterials[o.data.material]
              : nullptr;
      g_primKd = gmat ? gmat->kd : nullptr;
      g_primKe = gmat ? gmat->ke : nullptr;
      g_primTextured = gmat && gmat->texture;
      g_primUvRect = g_primTextured ? gmat->uvRect : nullptr;
      switch (o.data.type) {
        case 1: addSphere(b.vertices, b.colors, b.sts, o.data); break;
        case 2: addCylinder(b.vertices, b.colors, b.sts, o.data); break;
        case 3: addCone(b.vertices, b.colors, b.sts, o.data); break;
        case 12: addPlane(b.vertices, b.colors, b.sts, o.data); break;
        default: addBox(b.vertices, b.colors, b.sts, o.data); break;
      }
    }
  }
  g_primKd = nullptr;
  g_primKe = nullptr;
  g_primTextured = false;
  g_primUvRect = nullptr;
  g_aoOff = false;
  g_prelitTex = false;
  g_giProbeShade = false;
  if (b.vertices.empty()) {
    b.bag.reset();
    return;
  }
  // The arrays grew by push_back - up to twice what they hold - and a batch
  // keeps them for the whole scene. Trimmed before anything binds them.
  b.vertices.shrink_to_fit();
  b.colors.shrink_to_fit();
  b.sts.shrink_to_fit();
  if (!b.bag) {
    b.colorBag = std::make_unique<StaPipColorBag>();
    b.bag = std::make_unique<StaPipBag>();
    b.bag->info = batchInfoBag.get();
    b.bag->color = b.colorBag.get();
    b.bag->texture = nullptr;
    b.bag->lighting = nullptr;
  }
  b.colors.bind(b.colorBag);
  b.vertices.bind(b.bag);
  b.bag->count = static_cast<u32>(b.vertices.size());
  b.bag->bboxVersion = ++g_bboxStamp;  // geometry changed - fresh boxes
  if (b.texture) {
    if (!b.texBag) b.texBag = std::make_unique<StaPipTextureBag>();
    b.texBag->texture = b.texture;
    b.sts.bind(b.texBag);
    b.bag->texture = b.texBag.get();
  } else {
    b.bag->texture = nullptr;
  }
  // Strip batches draw PRIM_TRIANGLE_STRIP with every package exactly one
  // baked run, which is the same contract pinPackageSize enforces for a solo
  // stripped bag - so no package boundary can splice two members into one
  // triangle. A batch that had to fall back to a list for any member is
  // pinned the ordinary derived way instead.
  {
    std::vector<StaPipBag*> one{b.bag.get()};
    pinPackageSize(one, useStrips ? b.stripRun : 0u);
  }
  // World AABB for the split-screen band cull - the batch analogue of the
  // terrain chunks' build-time boxes.
  b.aabbMin[0] = b.aabbMax[0] = b.vertices[0].x;
  b.aabbMin[1] = b.aabbMax[1] = b.vertices[0].y;
  b.aabbMin[2] = b.aabbMax[2] = b.vertices[0].z;
  for (const Vec4& v : b.vertices) {
    if (v.x < b.aabbMin[0]) b.aabbMin[0] = v.x;
    if (v.x > b.aabbMax[0]) b.aabbMax[0] = v.x;
    if (v.y < b.aabbMin[1]) b.aabbMin[1] = v.y;
    if (v.y > b.aabbMax[1]) b.aabbMax[1] = v.y;
    if (v.z < b.aabbMin[2]) b.aabbMin[2] = v.z;
    if (v.z > b.aabbMax[2]) b.aabbMax[2] = v.z;
  }
}



bool TerrainGame::occlusionObjectIsOccluder(int index) const {
  return occlusionIsOccluder(currentScene,index);
}



void TerrainGame::buildOcclusionBuffer(){
  static int reportBeat=0;
  if(DEBUG_SHOW_PROFILER && OCCLUSION_CULLING && ++reportBeat>=120){
    TYRA_LOG("OCC proxies=",g_occProxies," hidden=",g_occHidden,"/",g_occTested);
    reportBeat=0;
  }
  g_occTested=g_occHidden=g_occProxies=0;
  if(!OCCLUSION_CULLING)return;
#if TYRA_FRAME_PROFILE
  u32 occT=Tyra::FrameProfile::ticks();
  ++ftrig::occBuilds;
#endif
  for(int i=0;i<OCC_W*OCC_H;++i)g_occDepth[i]=1e30F,g_occCover[i]=0;
#if TYRA_FRAME_PROFILE
  {const u32 n=Tyra::FrameProfile::ticks();ftrig::occLap[0]+=n-occT;occT=n;}
#endif
  g_occVp=engine->renderer.core.renderer3D.getViewProj();
  const auto& scr=engine->renderer.core.getSettings();
  g_occSx=4096.0F/scr.getRasterWidthF();
  g_occSy=4096.0F/scr.getRasterHeightF();
  // Every proxy box's eight world corners, cached. boxRotate evaluates Euler
  // trig and the EE has none in hardware: three rotations per occluder per
  // frame were most of what the buffer cost on a physical PS2. Occluders are
  // static by construction (codegen refuses anything that moves), and the key
  // below catches the ones a script or Live Link moves anyway.
  struct OccCornerCache{float key[10];float mn[3],mx[3];bool valid;};
  static std::vector<OccCornerCache> objKeys;
  static std::vector<V3> corners;  // 8 per box, OCCLUSION_BOXES order
  static unsigned int cornerGen=~0u;
  if(cornerGen!=sceneGeneration||objKeys.size()!=(size_t)OCCLUSION_OBJECT_COUNT){
    objKeys.assign((size_t)OCCLUSION_OBJECT_COUNT,OccCornerCache{});
    int boxes=0;
    for(int ri=0;ri<OCCLUSION_OBJECT_COUNT;++ri)
      boxes=std::max(boxes,OCCLUSION_OBJECTS[ri].first+OCCLUSION_OBJECTS[ri].count);
    corners.assign((size_t)boxes*8,V3{0.0F,0.0F,0.0F});
    cornerGen=sceneGeneration;
  }
  for(int ri=0;ri<OCCLUSION_OBJECT_COUNT;++ri){
    const OcclusionProxyObject& r=OCCLUSION_OBJECTS[ri];
    if(r.scene!=currentScene||r.object<0||r.object>=(int)runtimeObjects.size())continue;
    const RuntimeObject& o=runtimeObjects[r.object];
    if(!o.active||!o.visible)continue;
    const float key[10]={o.data.position[0],o.data.position[1],o.data.position[2],
      o.data.rotation[0],o.data.rotation[1],o.data.rotation[2],
      o.data.scale[0],o.data.scale[1],o.data.scale[2],o.data.modelYaw};
    OccCornerCache& ck=objKeys[(size_t)ri];
    bool same=ck.valid;
    for(int k=0;k<10&&same;++k)same=ck.key[k]==key[k];
    if(!same){
#if TYRA_FRAME_PROFILE
      ++ftrig::occRecomputes;
#endif
      const V3 ax=boxRotate({o.data.scale[0],0.0F,0.0F},o.data);
      const V3 ay=boxRotate({0.0F,o.data.scale[1],0.0F},o.data);
      const V3 az=boxRotate({0.0F,0.0F,o.data.scale[2]},o.data);
      for(int bi=0;bi<r.count;++bi){
        const OcclusionProxyBox& b=OCCLUSION_BOXES[r.first+bi];
        V3* v=&corners[(size_t)(r.first+bi)*8];
        for(int k=0;k<8;++k){
          const float x=k&1?b.mx[0]:b.mn[0],y=k&2?b.mx[1]:b.mn[1],z=k&4?b.mx[2]:b.mn[2];
          v[k]={o.data.position[0]+ax.x*x+ay.x*y+az.x*z,
                o.data.position[1]+ax.y*x+ay.y*y+az.y*z,
                o.data.position[2]+ax.z*x+ay.z*y+az.z*z};
        }
      }
      for(int a=0;a<3;++a){ck.mn[a]=1e30F;ck.mx[a]=-1e30F;}
      for(int k=0;k<r.count*8;++k){const V3& c=corners[(size_t)r.first*8+k];
        ck.mn[0]=std::min(ck.mn[0],c.x);ck.mx[0]=std::max(ck.mx[0],c.x);
        ck.mn[1]=std::min(ck.mn[1],c.y);ck.mx[1]=std::max(ck.mx[1],c.y);
        ck.mn[2]=std::min(ck.mn[2],c.z);ck.mx[2]=std::max(ck.mx[2],c.z);}
      for(int k=0;k<10;++k)ck.key[k]=key[k];
      ck.valid=true;
    }
    // A whole occluder outside the view writes nothing: one six-plane box test
    // instead of eight projections per proxy box. In a city most of them are
    // behind or beside the camera at any moment.
    {
#if TYRA_FRAME_PROFILE
      struct OccObjLap{u32 t0;~OccObjLap(){ftrig::occLap[6]+=Tyra::FrameProfile::ticks()-t0;}} occObjLap{Tyra::FrameProfile::ticks()};
#endif
      const Tyra::Vec4 omn(ck.mn[0],ck.mn[1],ck.mn[2],1.0F),omx(ck.mx[0],ck.mx[1],ck.mx[2],1.0F);
      if(Tyra::CoreBBox::frustumCheckAABB(
             engine->renderer.core.renderer3D.frustumPlanes.getAll(),omn,omx)==
         Tyra::CoreBBoxFrustum::OUTSIDE_FRUSTUM)continue;
    }
#if TYRA_FRAME_PROFILE
    ftrig::occBoxes+=(u32)r.count;
#endif
    for(int bi=0;bi<r.count;++bi)
      if(occBox(&corners[(size_t)(r.first+bi)*8]))++g_occProxies;  // near/tiny rejected inside
  }
#if TYRA_FRAME_PROFILE
  {const u32 n=Tyra::FrameProfile::ticks();
   // hull = everything since the clear minus the raster time occBox charged.
   static u64 rasterSeen=0;
   const u64 rasterNow=ftrig::occLap[2]-rasterSeen; rasterSeen=ftrig::occLap[2];
   ftrig::occLap[1]+=(n-occT)-(u32)rasterNow; occT=n;}
#endif
  // Erode coverage by one cell. Depth keeps the farthest proxy surface in a
  // covered cell; target tests add another world-depth bias below.
  for(int y=0;y<OCC_H;++y)for(int x=0;x<OCC_W;++x){
    bool on=g_occCover[y*OCC_W+x]!=0;
    for(int yy=y-1;yy<=y+1&&on;++yy)for(int xx=x-1;xx<=x+1;++xx)
      if(xx<0||yy<0||xx>=OCC_W||yy>=OCC_H||!g_occCover[yy*OCC_W+xx]){on=false;break;}
    g_occEroded[y*OCC_W+x]=on?1:0;
  }
#if TYRA_FRAME_PROFILE
  ftrig::occLap[3]+=Tyra::FrameProfile::ticks()-occT;
#endif
}



bool TerrainGame::occlusionHiddenAabb(const float* mn,const float* mx){
  if(!OCCLUSION_CULLING)return false;
  ++g_occTested;
#if TYRA_FRAME_PROFILE
  ++ftrig::occTests;
  struct OccTestLap{u32 t0;~OccTestLap(){ftrig::occLap[4]+=Tyra::FrameProfile::ticks()-t0;}} occTestLap{Tyra::FrameProfile::ticks()};
#endif
  // Most candidates in an open view cannot possibly be fully covered. Test
  // their centre before paying for eight corner transforms and a rectangle.
  V3 mid{(mn[0]+mx[0])*0.5F,(mn[1]+mx[1])*0.5F,(mn[2]+mx[2])*0.5F};
  float midX,midY,midW;
  if(!occProject(mid,midX,midY,midW))return false;
  const int midXi=(int)floorf(midX),midYi=(int)floorf(midY);
  if(midXi<0||midYi<0||midXi>=OCC_W||midYi>=OCC_H||
     !g_occEroded[midYi*OCC_W+midXi])return false;
  float x0=1e30F,y0=1e30F,x1=-1e30F,y1=-1e30F,nearW=1e30F;
  for(int k=0;k<8;++k){V3 p{k&1?mx[0]:mn[0],k&2?mx[1]:mn[1],k&4?mx[2]:mn[2]};
    float x,y,w;if(!occProject(p,x,y,w))return false;
    x0=std::min(x0,x);x1=std::max(x1,x);y0=std::min(y0,y);y1=std::max(y1,y);nearW=std::min(nearW,w);
  }
  int X0=(int)floorf(x0)-1,Y0=(int)floorf(y0)-1,X1=(int)ceilf(x1)+1,Y1=(int)ceilf(y1)+1;
  if(X0<0||Y0<0||X1>=OCC_W||Y1>=OCC_H)return false;
  for(int y=Y0;y<=Y1;++y)for(int x=X0;x<=X1;++x){const int i=y*OCC_W+x;
    if(!g_occEroded[i]||g_occDepth[i]+0.35F>=nearW)return false;}
  ++g_occHidden;return true;
}



bool TerrainGame::occlusionHiddenObject(int index){
  if(!occlusionCanCull(currentScene,index)||occlusionObjectIsOccluder(index))return false;
  if(index<0||index>=(int)runtimeObjects.size())return false;
  const RuntimeObject& o=runtimeObjects[index];
  // The world AABB below is three Euler rotations and eight corners - most of
  // the ~13 us a test cost on a physical PS2 - and for everything that does
  // not move it is the same box every frame. Cached per object, keyed on the
  // exact inputs, so anything that moves, turns or rescales recomputes.
  struct OccAabbCache{float key[10];float mn[3],mx[3];bool valid;};
  static std::vector<OccAabbCache> cache;
  static unsigned int cacheGen=~0u;
  if(cacheGen!=sceneGeneration||cache.size()!=runtimeObjects.size()){
    cache.assign(runtimeObjects.size(),OccAabbCache{});cacheGen=sceneGeneration;}
  OccAabbCache& ce=cache[(size_t)index];
  const float key[10]={o.data.position[0],o.data.position[1],o.data.position[2],
    o.data.rotation[0],o.data.rotation[1],o.data.rotation[2],
    o.data.scale[0],o.data.scale[1],o.data.scale[2],o.data.modelYaw};
  bool same=ce.valid&&!o.dirty;
  for(int k=0;k<10&&same;++k)same=ce.key[k]==key[k];
  if(same)return occlusionHiddenAabb(ce.mn,ce.mx);
  const CollisionBox b=objectCollisionBox(o);
  const V3 ax=boxRotate({1.0F,0.0F,0.0F},o.data),
           ay=boxRotate({0.0F,1.0F,0.0F},o.data),
           az=boxRotate({0.0F,0.0F,1.0F},o.data);
  float mn[3]={1e30F,1e30F,1e30F},mx[3]={-1e30F,-1e30F,-1e30F};
  for(int k=0;k<8;++k){const float x=b.center[0]+(k&1?b.half[0]:-b.half[0]),
    y=b.center[1]+(k&2?b.half[1]:-b.half[1]),z=b.center[2]+(k&4?b.half[2]:-b.half[2]);
    const float p[3]={o.data.position[0]+ax.x*x+ay.x*y+az.x*z,
      o.data.position[1]+ax.y*x+ay.y*y+az.y*z,
      o.data.position[2]+ax.z*x+ay.z*y+az.z*z};
    for(int a=0;a<3;++a){mn[a]=std::min(mn[a],p[a]);mx[a]=std::max(mx[a],p[a]);}}
  for(int k=0;k<10;++k)ce.key[k]=key[k];
  for(int a=0;a<3;++a){ce.mn[a]=mn[a];ce.mx[a]=mx[a];}
  ce.valid=true;
  return occlusionHiddenAabb(mn,mx);
}



void TerrainGame::renderStaticBatches() {
#if TYRA_FRAME_PROFILE
  stapip.core.setTelemetryProducer(Tyra::StaPipProducerStaticBatches);
#endif
  for (StaticBatch& b : staticBatches) {
    bool stale = b.dirty;
    for (size_t k = 0; k < b.members.size(); ++k) {
      const int object = b.members[k].object;
      const RuntimeObject& o = runtimeObjects[object];
      if (o.dirty) {
        objectBatchOf[object] = -1;  // demote: solo from now on
        b.members.erase(b.members.begin() + (long)k);
        b.shown.erase(b.shown.begin() + (long)k);
        --k;
        stale = true;
        continue;
      }
      if (!stale &&
          b.shown[k] != (unsigned char)((o.active && o.visible) ? 1 : 0))
        stale = true;
    }
    if (stale) rebuildStaticBatch(b);
    if (!b.bag || b.bag->count == 0) continue;
    // Draw distance, applied to the batch rather than to each member - the
    // per-frame analogue of beyondDrawDistance() and deliberately NOT routed
    // through the shown snapshot above, because a cut-off crossed while the
    // player drives is exactly the per-frame flip that would re-bake the
    // batch every frame and cost more than the submit it saves.
    //
    // The whole batch draws while the NEAREST point of the member-centre box
    // is inside the cut-off, so a member can outlive its own distance by up
    // to the spread of its batch (bounded by the grouping cell) but can never
    // disappear early. Over-drawing costs GS fill; disappearing early would
    // be a visible pop, and this frame is bag-bound, not fill-bound.
    if (b.drawDistance > 0.0F) {
      float d2 = 0.0F;
      const float c[3] = {cameraPosition.x, cameraPosition.y, cameraPosition.z};
      for (int a = 0; a < 3; ++a) {
        const float e = c[a] < b.ddMin[a]   ? b.ddMin[a] - c[a]
                        : c[a] > b.ddMax[a] ? c[a] - b.ddMax[a]
                                            : 0.0F;
        d2 += e * e;
      }
      if (d2 > b.drawDistance * b.drawDistance) continue;
    }
    // Split halves: same band early-out the terrain chunks use.
    if (splitBandActive && outsideSplitBand(b.aabbMin, b.aabbMax)) continue;
    // The batch is world space (identity model) and aabbMin/Max is exactly
    // its vertex box, so this is the test StaPip's own main-bbox check would
    // make, with the same planes and the same verdict - without entering
    // render() for it. The road chunks do the same.
    {
      const Tyra::Vec4 mn(b.aabbMin[0], b.aabbMin[1], b.aabbMin[2], 1.0F);
      const Tyra::Vec4 mx(b.aabbMax[0], b.aabbMax[1], b.aabbMax[2], 1.0F);
      if (Tyra::CoreBBox::frustumCheckAABB(
              engine->renderer.core.renderer3D.frustumPlanes.getAll(), mn, mx) ==
          Tyra::CoreBBoxFrustum::OUTSIDE_FRUSTUM)
        continue;
    }
    bool ownsOccluder = false;
    for (const StaticBatchMember& m : b.members)
      if (occlusionObjectIsOccluder(m.object)) { ownsOccluder = true; break; }
    if (!ownsOccluder && occlusionHiddenAabb(b.aabbMin, b.aabbMax)) continue;
    submitHeavy(b.bag.get());
  }
}



void TerrainGame::procBlockVertexAo(float x, float y, float z,
                                    unsigned char faces,
                                    unsigned char out[24]) const {
  for (int i = 0; i < 24; ++i) out[i] = 255;  // 255 = open sky
  if (!procBlocks.active || !SCENE_AO_ENABLED) return;
  // Sample the whole neighbourhood once - 26 field lookups instead of the 72
  // the corners would ask for separately, and each corner below is then three
  // bit tests. Offsets are taken from the block's CENTRE, so a lattice cell
  // can never be missed by a rounding edge.
  const float c = procBlocks.cell;
  unsigned int nb = 0u;
  for (int dz = -1; dz <= 1; ++dz)
    for (int dy = -1; dy <= 1; ++dy)
      for (int dx = -1; dx <= 1; ++dx)
        if (procBlockSolid(x + (float)dx * c, y + (float)dy * c,
                           z + (float)dz * c))
          nb |= 1u << ((dz + 1) * 9 + (dy + 1) * 3 + (dx + 1));

  for (int f = 0; f < 6; ++f) {
    if (!(faces & (1 << f))) continue;  // buried: nothing will read it
    const int na = kProcFaceAxis[f], ua = kProcFaceU[f], va = kProcFaceV[f];
    for (int corner = 0; corner < 4; ++corner) {
      const int us = (corner & 1) ? 1 : -1;
      const int vs = (corner & 2) ? 1 : -1;
      // The three cells sharing this corner, in the plane just OUTSIDE the
      // face: the two edge neighbours and the diagonal between them.
      int s1[3] = {0, 0, 0}, s2[3] = {0, 0, 0}, dg[3] = {0, 0, 0};
      s1[na] = s2[na] = dg[na] = kProcFaceDir[f];
      s1[ua] = us;
      s2[va] = vs;
      dg[ua] = us;
      dg[va] = vs;
      const int a = procNbSolid(nb, s1[0], s1[1], s1[2]) ? 1 : 0;
      const int b = procNbSolid(nb, s2[0], s2[1], s2[2]) ? 1 : 0;
      const int g = procNbSolid(nb, dg[0], dg[1], dg[2]) ? 1 : 0;
      // Two solid edge neighbours wall the corner in completely and the
      // diagonal behind them cannot make it darker; otherwise each of the
      // three takes it down one step of four.
      const int t = (a && b) ? 0 : 3 - (a + b + g);
      out[f * 4 + corner] = (unsigned char)(t * 85);
    }
  }
}



void TerrainGame::procAddMergedObject(int owner, int instance,
                                      const SceneObjectData& d,
                                      unsigned char faces,
                                      const unsigned char* blockAo) {
  const float cell =
      owner >= 0 ? procrt::VOLUMES[owner].cell : 100000.0F;  // one bag per prefab
  const int cx = (int)floorf(d.position[0] / cell);
  const int cz = (int)floorf(d.position[2] / cell);

  // Analytic lights are pruned PER OBJECT (pushVert reads the g_*Local lists),
  // exactly as rebuildStaticBatch does for its members - collecting once for a
  // whole chunk would shade every instance with the first one's neighbours.
  {
    const float sx = d.scale[0], sy = d.scale[1], sz = d.scale[2];
    const float rad = 0.87F * sqrtf(sx * sx + sy * sy + sz * sz);
    aoCollectLocal(d.position[0], d.position[1], d.position[2], rad, -1);
    emisCollectLocal(d.position[0], d.position[1], d.position[2], rad, -1);
  }
  // Generated geometry never carries a lightmap region: the atlas is baked per
  // authored object and this object did not exist at bake time. The probe grid
  // is what lights it, and these are globals, so state them rather than
  // inheriting whatever the last rebuild left set.
  g_aoAtlas = false;
  g_emisAtlas = false;
  g_aoSts = nullptr;
  // Imported models take no per-vertex occlusion - on an authored low-poly
  // mesh it reads as triangulated shading (docs/ambient-occlusion.md). A
  // BLOCK is the exception the rule was never about: two triangles per flat
  // square face is exactly the geometry a corner gradient resolves well, so a
  // table from procBlockVertexAo is what turns the vertex path back on.
  g_aoOff = d.type == 5 && !blockAo;
  g_giLightmap = false;
  g_giProbeShade = SCENE_PROBES != nullptr;
  g_litNormals = nullptr;
  g_envNormals = nullptr;
  g_bakeLocal = false;

  if (d.collision != 2) {
    // Conservative world AABB of the (possibly yawed) box: the largest extent
    // wins on each axis, so a rotated wall is never smaller than it looks.
    const float ex = 0.5F * fabsf(d.scale[0]);
    const float ey = 0.5F * fabsf(d.scale[1]);
    const float ez = 0.5F * fabsf(d.scale[2]);
    const float rad = d.rotation[1] * 0.01745329F;
    const float ca = fabsf(cosf(rad)), sa = fabsf(sinf(rad));
    const float wx = ex * ca + ez * sa;
    const float wz = ex * sa + ez * ca;
    StaticBox b;
    b.mn[0] = d.position[0] - wx;
    b.mx[0] = d.position[0] + wx;
    b.mn[1] = d.position[1] - ey;
    b.mx[1] = d.position[1] + ey;
    b.mn[2] = d.position[2] - wz;
    b.mx[2] = d.position[2] + wz;
    b.owner = (short)owner;
    b.instance = (short)instance;
    procColliders.push_back(b);
  }

  // Per-vertex AO is only worth computing if the rasterizer reads it ACROSS
  // the triangle - flat shading takes one corner and paints the whole triangle
  // with it, which turns a corner gradient into a hard diagonal seam down every
  // face. Measured before this existed: one block face came out as two flat
  // plateaus 42 levels apart instead of a gradient.
  const bool wantSmooth = blockAo != nullptr;

  auto chunkFor = [&](int model, int part, int material) -> ProcChunk& {
    for (ProcChunk& c : procChunks)
      if (c.owner == owner && c.instance == instance && c.model == model &&
          c.part == part && c.material == material && c.cx == cx && c.cz == cz) {
        c.smooth = c.smooth || wantSmooth;
        return c;
      }
    procChunks.emplace_back();
    ProcChunk& c = procChunks.back();
    c.smooth = wantSmooth;
    c.owner = owner;
    c.instance = instance;
    c.model = model;
    c.part = part;
    c.material = material;
    c.cx = cx;
    c.cz = cz;
    c.drawDist = owner >= 0 ? procrt::VOLUMES[owner].drawDist : 0.0F;
    return c;
  };

  if (d.type == 5) {
    if (d.model < 0 || d.model >= (int)gameModels.size()) return;
    const GameModel& gm = gameModels[d.model];
    for (int pi = 0; pi < (int)gm.parts.size(); ++pi) {
      const GameModelPart& src = gm.parts[pi];
      if (src.verts.empty()) continue;
      ProcChunk& c = chunkFor(d.model, pi, -1);
      const bool textured = src.texture != nullptr;
      const bool hasAo = src.vertexAo.size() * 8 == src.verts.size();
      // Whole triangles, so a dropped face takes all of its triangles with it.
      for (size_t i = 0; i + 23 < src.verts.size(); i += 24) {
        // The face this triangle belongs to answers two questions at once -
        // whether a neighbour covers it, and which four corner AO levels its
        // vertices interpolate - so it is resolved once, and only when
        // somebody is going to ask.
        const float* v0 = &src.verts[i];
        const int face = (faces != 63 || blockAo)
                             ? faceOfNormal(v0[3], v0[4], v0[5])
                             : -1;
        if (faces != 63 && face >= 0 && !(faces & (1 << face))) continue;
        for (int k = 0; k < 3; ++k) {
          const float* v = &src.verts[i + k * 8];
          unsigned char vao =
              hasAo ? src.vertexAo[(i + k * 8) / 8] : (unsigned char)255;
          // A block's own lattice wins over a baked .aov sidecar: the sidecar
          // describes the cube in isolation, the lattice describes where this
          // copy of it actually sits.
          if (blockAo && face >= 0) vao = procBlockAoAt(blockAo, face, v);
          pushVert(c.vertices, c.colors, c.sts, d, {v[0], v[1], v[2]},
                   {v[3], v[4], v[5]}, v[6], v[7], src.kd, textured, vao,
                   src.ke);
        }
      }
    }
    return;
  }

  const GameMaterial* gmat =
      (d.material >= 0 && d.material < (int)gameMaterials.size())
          ? &gameMaterials[d.material]
          : nullptr;
  ProcChunk& c = chunkFor(-1, 0, d.material);
  g_primKd = gmat ? gmat->kd : nullptr;
  g_primKe = gmat ? gmat->ke : nullptr;
  g_primTextured = gmat && gmat->texture;
  g_primUvRect = g_primTextured ? gmat->uvRect : nullptr;
  switch (d.type) {
    case 1: addSphere(c.vertices, c.colors, c.sts, d); break;
    case 2: addCylinder(c.vertices, c.colors, c.sts, d); break;
    case 3: addCone(c.vertices, c.colors, c.sts, d); break;
    case 12: addPlane(c.vertices, c.colors, c.sts, d); break;
    default: addBox(c.vertices, c.colors, c.sts, d); break;
  }
  g_primKd = nullptr;
  g_primKe = nullptr;
  g_primTextured = false;
  g_primUvRect = nullptr;
}



// Wires the bags of every chunk that gained vertices and computes its box.
// Called once after a generation pass rather than per instance: a bag pointing
// at a vector that is still growing is a dangling pointer the moment it
// reallocates.
void TerrainGame::procFinishChunks() {
  g_giProbeShade = false;
  // The batch info bag is shared with the static batcher, but that one is only
  // built when static batching is on - generated geometry needs it either way.
  if (!batchInfoBag) {
    batchInfoBag = std::make_unique<StaPipInfoBag>();
    batchInfoBag->model = &model;
    batchInfoBag->shadingType = TyraShadingGouraud;
    batchInfoBag->frustumCulling = PipelineInfoBagFrustumCulling_Precise;
    batchInfoBag->fullClipChecks = true;
  }
  // Its Gouraud twin, built only once a chunk asks for it - a project with no
  // block world never allocates it.
  for (const ProcChunk& c : procChunks)
    if (c.smooth && !c.vertices.empty() && !procSmoothInfoBag) {
      procSmoothInfoBag = std::make_unique<StaPipInfoBag>();
      procSmoothInfoBag->model = &model;
      procSmoothInfoBag->shadingType = TyraShadingGouraud;
      procSmoothInfoBag->frustumCulling = PipelineInfoBagFrustumCulling_Precise;
      procSmoothInfoBag->fullClipChecks = true;
      break;
    }
  for (ProcChunk& c : procChunks) {
    if (c.vertices.empty()) {
      c.bag.reset();
      continue;
    }
    if (!c.bag) {
      c.colorBag = std::make_unique<StaPipColorBag>();
      c.bag = std::make_unique<StaPipBag>();
      c.bag->color = c.colorBag.get();
      c.bag->lighting = nullptr;
    }
    // Re-stated every pass, not only on creation: a regeneration reuses the
    // chunk, and a world whose blocks moved may have gained or lost the AO.
    c.bag->info = c.smooth ? procSmoothInfoBag.get() : batchInfoBag.get();
    if (c.roadBlend || c.roadEdge) {
      // A spill is alpha-over by its vertex alpha (the fade) on the road
      // under it, a soft edge on the terrain: the painted terrain layer's
      // arrangement.
      if (!roadBlendInfoBag) {
        roadBlendInfoBag = std::make_unique<StaPipInfoBag>();
        roadBlendInfoBag->model = &model;
        roadBlendInfoBag->shadingType = TyraShadingGouraud;
        roadBlendInfoBag->frustumCulling = PipelineInfoBagFrustumCulling_Precise;
        roadBlendInfoBag->fullClipChecks = true;
        roadBlendInfoBag->blendingEnabled = true;
      }
      c.bag->info = roadBlendInfoBag.get();
    }
    c.colors.bind(c.colorBag);
    c.vertices.bind(c.bag);
    c.bag->count = static_cast<u32>(c.vertices.size());
    // Triangle strips (docs/model-pipeline.md). A stripped chunk's array is
    // already chopped into self-contained runs, so the package size is PINNED
    // to the run rather than derived: StaPipCore slices a bag at multiples of
    // it, and a boundary anywhere else would fuse two strips. Nothing else is
    // derived either - the run is by construction no larger than any static
    // class's own capacity, which is what buildRoads checks before baking it.
    // Re-stated every pass, like the info bag above: a regeneration may have
    // turned a chunk from one representation into the other.
    c.bag->stripped = c.stripRun > 0;
    c.bag->packageSize = c.stripRun > 0 ? static_cast<u32>(c.stripRun) : 0U;
    c.bag->bboxVersion = ++g_bboxStamp;
    const Tyra::Texture* tex = c.roadTex;
    if (tex) {
    } else if (c.model >= 0 && c.model < (int)gameModels.size() &&
        c.part < (int)gameModels[c.model].parts.size())
      tex = gameModels[c.model].parts[c.part].texture;
    else if (c.material >= 0 && c.material < (int)gameMaterials.size())
      tex = gameMaterials[c.material].texture;
    if (tex) {
      if (!c.texBag) c.texBag = std::make_unique<StaPipTextureBag>();
      c.texBag->texture = const_cast<Tyra::Texture*>(tex);
      c.sts.bind(c.texBag);
      c.bag->texture = c.texBag.get();
    } else {
      c.bag->texture = nullptr;
    }
    c.aabbMin[0] = c.aabbMax[0] = c.vertices[0].x;
    c.aabbMin[1] = c.aabbMax[1] = c.vertices[0].y;
    c.aabbMin[2] = c.aabbMax[2] = c.vertices[0].z;
    for (const Vec4& v : c.vertices) {
      if (v.x < c.aabbMin[0]) c.aabbMin[0] = v.x;
      if (v.x > c.aabbMax[0]) c.aabbMax[0] = v.x;
      if (v.y < c.aabbMin[1]) c.aabbMin[1] = v.y;
      if (v.y > c.aabbMax[1]) c.aabbMax[1] = v.y;
      if (v.z < c.aabbMin[2]) c.aabbMin[2] = v.z;
      if (v.z > c.aabbMax[2]) c.aabbMax[2] = v.z;
    }
    for (int a = 0; a < 3; ++a)
      c.centre[a] = 0.5F * (c.aabbMin[a] + c.aabbMax[a]);
  }
}



/*  */
/*  */
void TerrainGame::renderProcChunks() {
#if TYRA_FRAME_PROFILE
  stapip.core.setTelemetryProducer(Tyra::StaPipProducerProcedural);
#endif
  if (procChunks.empty()) return;
  for (ProcChunk& c : procChunks) {
    // Roads have their own phase and profiler row. Keeping them here as well
    // used to make "Procedural" mean "mostly asphalt" and would double-draw
    // them now that the main view calls renderRoadChunks explicitly.
    if (c.owner == -3) continue;
    if (!c.bag || c.bag->count == 0) continue;
    // StaPip has its own precise clipper, but entering it for every generated
    // road/prefab chunk still pays the bag setup and classification cost. The
    // chunks already own world-space bounds, so reject wholly invisible ones
    // here and leave only intersecting chunks to the pipeline's safe clipper.
    const Tyra::Vec4 mn(c.aabbMin[0], c.aabbMin[1], c.aabbMin[2], 1.0F);
    const Tyra::Vec4 mx(c.aabbMax[0], c.aabbMax[1], c.aabbMax[2], 1.0F);
    if (Tyra::CoreBBox::frustumCheckAABB(
            engine->renderer.core.renderer3D.frustumPlanes.getAll(), mn, mx) ==
        Tyra::CoreBBoxFrustum::OUTSIDE_FRUSTUM)
      continue;
    // Per-chunk draw distance: the cheapest LOD there is, and the reason
    // chunk size is a real authoring decision rather than a detail.
    if (c.drawDist > 0.0F) {
      const float dx = c.centre[0] - cameraPosition.x;
      const float dy = c.centre[1] - cameraPosition.y;
      const float dz = c.centre[2] - cameraPosition.z;
      if (dx * dx + dy * dy + dz * dz > c.drawDist * c.drawDist) continue;
    }
    if (splitBandActive && outsideSplitBand(c.aabbMin, c.aabbMax)) continue;
    if (occlusionHiddenAabb(c.aabbMin, c.aabbMax)) continue;
    stapip.core.render(c.bag.get());
  }
}
}
